CREATE OR REPLACE FUNCTION public.admin_set_member_nickname(p_profile_id uuid, p_nickname text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_actor_profile public.profiles%rowtype;
    v_target public.profiles%rowtype;
    v_login_name text;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    v_actor := auth.uid();

    if v_actor is null then
        raise exception 'AUTH_REQUIRED';
    end if;

    select *
    into v_actor_profile
    from public.profiles
    where id = v_actor;

    if not found then
        raise exception 'PROFILE_NOT_FOUND';
    end if;

    if coalesce(v_actor_profile.is_active, false) is not true then
        raise exception 'ACCOUNT_INACTIVE';
    end if;

    if upper(coalesce(v_actor_profile.role, '')) <> 'ADMIN' then
        raise exception 'ADMIN_REQUIRED';
    end if;

    if p_profile_id is null then
        raise exception 'TARGET_PROFILE_REQUIRED';
    end if;

    select *
    into v_target
    from public.profiles
    where id = p_profile_id
    for update;

    if not found then
        raise exception 'TARGET_PROFILE_NOT_FOUND';
    end if;

    if upper(coalesce(v_target.role, '')) <> 'MEMBER' then
        raise exception 'TARGET_MUST_BE_MEMBER';
    end if;

    if coalesce(v_target.is_active, false) is not true then
        raise exception 'TARGET_ACCOUNT_INACTIVE';
    end if;

    if nullif(btrim(v_target.login_name), '') is not null then
        raise exception 'LOGIN_NAME_ALREADY_SET';
    end if;

    v_login_name := lower(btrim(coalesce(p_nickname, '')));

    if v_login_name = '' then
        raise exception 'LOGIN_NAME_REQUIRED';
    end if;

    if char_length(v_login_name) < 3
       or char_length(v_login_name) > 32 then
        raise exception 'LOGIN_NAME_INVALID_LENGTH';
    end if;

    if v_login_name !~ '^[a-z0-9._-]{3,32}$' then
        raise exception 'LOGIN_NAME_INVALID_FORMAT';
    end if;

    if exists (
        select 1
        from public.profiles p
        where p.login_name is not null
          and lower(p.login_name) = v_login_name
          and p.id <> p_profile_id
    ) then
        raise exception 'LOGIN_NAME_TAKEN';
    end if;

    begin
        update public.profiles
        set
            login_name = v_login_name,
            updated_at = now()
        where id = p_profile_id;
    exception
        when unique_violation then
            raise exception 'LOGIN_NAME_TAKEN';
    end;

    insert into public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason,
        created_at
    )
    values (
        v_actor,
        'ADMIN_SET_MEMBER_NICKNAME',
        'profiles',
        p_profile_id,
        jsonb_build_object(
            'login_name', v_target.login_name,
            'role', v_target.role,
            'is_active', v_target.is_active
        ),
        jsonb_build_object(
            'login_name', v_login_name,
            'role', v_target.role,
            'is_active', v_target.is_active
        ),
        'IAM06_ADMIN_LEGACY_LOGIN_NAME_ASSIGNMENT',
        now()
    );

    return jsonb_build_object(
        'success', true,
        'profile_id', p_profile_id,
        'login_name', v_login_name
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_rating_match_weight(p_match_type text, p_weight numeric, p_description text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_user_id uuid;
    v_old_weight numeric;
    v_old_description text;
    v_new_description text;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    -- AUTH
    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception 'AUTH_REQUIRED';
    end if;

    if not exists (
        select 1
        from public.profiles p
        where p.id = v_user_id
          and p.role = 'ADMIN'
          and p.is_active = true
    ) then
        raise exception 'ADMIN_REQUIRED';
    end if;

    -- INPUT
    if p_match_type is null
       or btrim(p_match_type) = '' then
        raise exception 'match_type không được để trống';
    end if;

    if p_weight is null
       or p_weight < 0
       or p_weight > 1 then
        raise exception 'weight phải nằm trong khoảng 0 đến 1';
    end if;

    v_new_description :=
        nullif(btrim(p_description), '');

    -- LOCK + LOAD EXISTING CONFIG
    select
        rw.weight,
        rw.description
    into
        v_old_weight,
        v_old_description
    from public.rating_match_weights rw
    where rw.match_type = btrim(p_match_type)
    for update;

    if not found then
        raise exception
            'Không tồn tại match_type: %',
            btrim(p_match_type);
    end if;

    -- NO-OP
    if v_old_weight is not distinct from p_weight
       and v_old_description is not distinct from v_new_description then

        return jsonb_build_object(
            'success', true,
            'changed', false,
            'match_type', btrim(p_match_type),
            'weight', v_old_weight,
            'description', v_old_description
        );
    end if;

    -- UPDATE
    update public.rating_match_weights
    set
        weight = p_weight,
        description = v_new_description
    where match_type = btrim(p_match_type);

    -- AUDIT
    insert into public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason,
        created_at
    )
    values (
        v_user_id,
        'UPDATE_RATING_MATCH_WEIGHT',
        'rating_match_weights',
        null,
        jsonb_build_object(
            'match_type', btrim(p_match_type),
            'weight', v_old_weight,
            'description', v_old_description
        ),
        jsonb_build_object(
            'match_type', btrim(p_match_type),
            'weight', p_weight,
            'description', v_new_description
        ),
        'ADMIN cập nhật trọng số loại trận',
        now()
    );

    return jsonb_build_object(
        'success', true,
        'changed', true,
        'match_type', btrim(p_match_type),
        'old_weight', v_old_weight,
        'new_weight', p_weight,
        'description', v_new_description
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_match(p_match_id uuid, p_algorithm_version text DEFAULT 'V1.1'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid;
  v_role text;
  v_is_active boolean;
  v_can_approve_matches boolean;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Bạn chưa đăng nhập hoặc phiên đăng nhập không hợp lệ';
  end if;

  select
    role,
    is_active,
    can_approve_matches
  into
    v_role,
    v_is_active,
    v_can_approve_matches
  from public.profiles
  where id = v_user_id;

  if not found then
    raise exception 'Không tìm thấy hồ sơ người dùng';
  end if;

  if coalesce(v_is_active, false) = false then
    raise exception 'Tài khoản đã bị vô hiệu hóa';
  end if;

  if upper(coalesce(v_role, '')) <> 'ADMIN'
     and coalesce(v_can_approve_matches, false) = false then
    raise exception 'MATCH_APPROVAL_PERMISSION_REQUIRED';
  end if;

  return public._approve_match_internal(
    p_match_id,
    p_algorithm_version,
    v_user_id,
    null
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_match_active(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
  return public.approve_match(
    p_match_id,
    public._get_active_rating_version()
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.change_tournament_registration_status(p_registration_id uuid, p_new_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_uid uuid;
    v_profile public.profiles%rowtype;
    v_registration public.tournament_registrations%rowtype;
    v_old_registration public.tournament_registrations%rowtype;
    v_tournament public.tournaments%rowtype;
    v_new_status text;
    v_reason text;
    v_amount_paid numeric := 0;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    v_uid := auth.uid();

    if v_uid is null then
        raise exception 'AUTH_REQUIRED';
    end if;

    select *
    into v_profile
    from public.profiles
    where id = v_uid;

    if not found then
        raise exception 'PROFILE_NOT_FOUND';
    end if;

    if coalesce(v_profile.is_active, false) = false then
        raise exception 'PROFILE_INACTIVE';
    end if;

    if upper(coalesce(v_profile.role, '')) <> 'ADMIN'
       and coalesce(v_profile.can_manage_tournaments, false) = false then
        raise exception 'TOURNAMENT_MANAGEMENT_PERMISSION_REQUIRED';
    end if;

    if p_registration_id is null then
        raise exception 'REGISTRATION_ID_REQUIRED';
    end if;

    v_new_status :=
        upper(
            btrim(
                coalesce(
                    p_new_status,
                    ''
                )
            )
        );

    if v_new_status not in (
        'DANG_KY',
        'DA_XAC_NHAN',
        'HUY'
    ) then
        raise exception 'INVALID_REGISTRATION_STATUS';
    end if;

    v_reason :=
        btrim(
            coalesce(
                p_reason,
                ''
            )
        );

    if v_reason = '' then
        raise exception 'REASON_REQUIRED';
    end if;

    /*
     * Serialize status changes for this registration.
     * Future payment RPC should use the same registration row lock.
     */
    select *
    into v_registration
    from public.tournament_registrations
    where id = p_registration_id
    for update;

    if not found then
        raise exception 'REGISTRATION_NOT_FOUND';
    end if;

    v_old_registration :=
        v_registration;

    select *
    into v_tournament
    from public.tournaments
    where id = v_registration.tournament_id;

    if not found then
        raise exception 'TOURNAMENT_NOT_FOUND';
    end if;

    if upper(v_registration.status) = 'HUY' then
        raise exception 'REGISTRATION_ALREADY_CANCELLED';
    end if;

    if upper(v_registration.status) = v_new_status then
        raise exception 'REGISTRATION_STATUS_UNCHANGED';
    end if;

    /*
     * Allowed lifecycle:
     *
     * DANG_KY
     *   -> DA_XAC_NHAN
     *   -> HUY
     *
     * DA_XAC_NHAN
     *   -> HUY
     *
     * HUY
     *   -> terminal
     */
    if upper(v_registration.status) = 'DANG_KY' then
        if v_new_status not in (
            'DA_XAC_NHAN',
            'HUY'
        ) then
            raise exception 'INVALID_REGISTRATION_STATUS_TRANSITION';
        end if;

    elsif upper(v_registration.status) = 'DA_XAC_NHAN' then
        if v_new_status <> 'HUY' then
            raise exception 'INVALID_REGISTRATION_STATUS_TRANSITION';
        end if;

    else
        raise exception 'INVALID_CURRENT_REGISTRATION_STATUS';
    end if;

    /*
     * Registration management is closed once tournament
     * is already running or later.
     */
    if upper(v_tournament.status) not in (
        'DU_KIEN',
        'MO_DANG_KY'
    ) then
        raise exception 'TOURNAMENT_REGISTRATION_CLOSED';
    end if;

    /*
     * Never cancel a registration that already has cash recorded.
     * Refund workflow will be designed separately.
     */
    if v_new_status = 'HUY' then
        select coalesce(
            sum(tp.amount),
            0
        )
        into v_amount_paid
        from public.tournament_payments tp
        where tp.registration_id =
            v_registration.id;

        if v_amount_paid > 0 then
            raise exception 'REGISTRATION_HAS_PAYMENT';
        end if;
    end if;

    update public.tournament_registrations
    set status = v_new_status
    where id = v_registration.id
    returning *
    into v_registration;

    insert into public.audit_logs(
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason
    )
    values (
        v_uid,
        'CHANGE_TOURNAMENT_REGISTRATION_STATUS',
        'tournament_registrations',
        v_registration.id,
        to_jsonb(v_old_registration),
        to_jsonb(v_registration),
        v_reason
    );

    return jsonb_build_object(
        'ok',
        true,
        'registration_id',
        v_registration.id,
        'tournament_id',
        v_registration.tournament_id,
        'old_status',
        v_old_registration.status,
        'new_status',
        v_registration.status,
        'amount_paid',
        v_amount_paid
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.change_tournament_status(p_tournament_id uuid, p_new_status text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_profile public.profiles%rowtype;

    v_old public.tournaments%rowtype;
    v_new public.tournaments%rowtype;

    v_target_status text;
    v_reason text;

    v_pending_matches integer := 0;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    v_actor := auth.uid();

    if v_actor is null then
        raise exception 'AUTH_REQUIRED';
    end if;

    select *
    into v_profile
    from public.profiles
    where id = v_actor;

    if not found then
        raise exception 'PROFILE_NOT_FOUND';
    end if;

    if v_profile.is_active is not true then
        raise exception 'ACCOUNT_INACTIVE';
    end if;

    if upper(coalesce(v_profile.role, '')) <> 'ADMIN'
       and coalesce(v_profile.can_manage_tournaments, false) = false then
        raise exception 'TOURNAMENT_MANAGEMENT_PERMISSION_REQUIRED';
    end if;

    if p_tournament_id is null then
        raise exception 'TOURNAMENT_ID_REQUIRED';
    end if;

    v_target_status :=
        upper(
            nullif(
                btrim(p_new_status),
                ''
            )
        );

    if v_target_status is null then
        raise exception 'TOURNAMENT_STATUS_REQUIRED';
    end if;

    if v_target_status not in (
        'DU_KIEN',
        'MO_DANG_KY',
        'DANG_DIEN_RA',
        'DA_KET_THUC',
        'DA_QUYET_TOAN',
        'HUY'
    ) then
        raise exception 'INVALID_TOURNAMENT_STATUS';
    end if;

    v_reason :=
        nullif(
            btrim(p_reason),
            ''
        );

    /*
      Lock tournament row:
      tránh hai ADMIN đổi lifecycle cùng lúc.
    */
    select *
    into v_old
    from public.tournaments
    where id = p_tournament_id
    for update;

    if not found then
        raise exception 'TOURNAMENT_NOT_FOUND';
    end if;

    if v_old.status = v_target_status then
        raise exception 'TOURNAMENT_STATUS_UNCHANGED';
    end if;

    /*
      Strict lifecycle state machine.
      Không nhảy cóc và không quay ngược trạng thái.
    */
    if v_old.status = 'DU_KIEN' then
        if v_target_status not in (
            'MO_DANG_KY',
            'HUY'
        ) then
            raise exception
                'INVALID_STATUS_TRANSITION: % -> %',
                v_old.status,
                v_target_status;
        end if;

    elsif v_old.status = 'MO_DANG_KY' then
        if v_target_status not in (
            'DANG_DIEN_RA',
            'HUY'
        ) then
            raise exception
                'INVALID_STATUS_TRANSITION: % -> %',
                v_old.status,
                v_target_status;
        end if;

    elsif v_old.status = 'DANG_DIEN_RA' then
        if v_target_status <> 'DA_KET_THUC' then
            raise exception
                'INVALID_STATUS_TRANSITION: % -> %',
                v_old.status,
                v_target_status;
        end if;

    elsif v_old.status = 'DA_KET_THUC' then
        if v_target_status <> 'DA_QUYET_TOAN' then
            raise exception
                'INVALID_STATUS_TRANSITION: % -> %',
                v_old.status,
                v_target_status;
        end if;

    elsif v_old.status in (
        'DA_QUYET_TOAN',
        'HUY'
    ) then
        raise exception
            'TOURNAMENT_STATUS_TERMINAL: %',
            v_old.status;

    else
        raise exception
            'UNKNOWN_CURRENT_TOURNAMENT_STATUS: %',
            v_old.status;
    end if;

    /*
      Không cho kết thúc/quyết toán khi vẫn còn
      trận PENDING thuộc giải.
    */
    if v_target_status in (
        'DA_KET_THUC',
        'DA_QUYET_TOAN'
    ) then
        select count(*)::integer
        into v_pending_matches
        from public.matches
        where tournament_id = p_tournament_id
          and status = 'PENDING';

        if v_pending_matches > 0 then
            raise exception
                'TOURNAMENT_HAS_PENDING_MATCHES: %',
                v_pending_matches;
        end if;
    end if;

    update public.tournaments
    set
        status = v_target_status,
        updated_at = now()
    where id = p_tournament_id
    returning *
    into v_new;

    insert into public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason
    )
    values (
        v_actor,
        'CHANGE_TOURNAMENT_STATUS',
        'tournaments',
        v_new.id,
        to_jsonb(v_old),
        to_jsonb(v_new),
        coalesce(
            v_reason,
            'Chuyển trạng thái giải: ' ||
            v_old.status ||
            ' -> ' ||
            v_new.status
        )
    );

    return jsonb_build_object(
        'success', true,
        'tournament_id', v_new.id,
        'name', v_new.name,
        'old_status', v_old.status,
        'new_status', v_new.status,
        'pending_matches', v_pending_matches,
        'updated_at', v_new.updated_at
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_my_nickname(p_nickname text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_profile public.profiles%rowtype;
    v_login_name text;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    v_actor := auth.uid();

    if v_actor is null then
        raise exception 'AUTH_REQUIRED';
    end if;

    select *
    into v_profile
    from public.profiles
    where id = v_actor
    for update;

    if not found then
        raise exception 'PROFILE_NOT_FOUND';
    end if;

    if coalesce(v_profile.is_active, false) is not true then
        raise exception 'ACCOUNT_INACTIVE';
    end if;

    if upper(coalesce(v_profile.role, '')) <> 'MEMBER' then
        raise exception 'MEMBER_ROLE_REQUIRED';
    end if;

    if nullif(btrim(v_profile.login_name), '') is not null then
        raise exception 'LOGIN_NAME_ALREADY_SET';
    end if;

    v_login_name := lower(btrim(coalesce(p_nickname, '')));

    if v_login_name = '' then
        raise exception 'LOGIN_NAME_REQUIRED';
    end if;

    if char_length(v_login_name) < 3
       or char_length(v_login_name) > 32 then
        raise exception 'LOGIN_NAME_INVALID_LENGTH';
    end if;

    if v_login_name !~ '^[a-z0-9._-]{3,32}$' then
        raise exception 'LOGIN_NAME_INVALID_FORMAT';
    end if;

    if exists (
        select 1
        from public.profiles p
        where p.login_name is not null
          and lower(p.login_name) = v_login_name
          and p.id <> v_actor
    ) then
        raise exception 'LOGIN_NAME_TAKEN';
    end if;

    begin
        update public.profiles
        set
            login_name = v_login_name,
            updated_at = now()
        where id = v_actor;
    exception
        when unique_violation then
            raise exception 'LOGIN_NAME_TAKEN';
    end;

    insert into public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason,
        created_at
    )
    values (
        v_actor,
        'CLAIM_MY_NICKNAME',
        'profiles',
        v_actor,
        jsonb_build_object(
            'login_name', v_profile.login_name
        ),
        jsonb_build_object(
            'login_name', v_login_name
        ),
        'IAM06_MEMBER_LEGACY_LOGIN_NAME_CLAIM',
        now()
    );

    return jsonb_build_object(
        'success', true,
        'profile_id', v_actor,
        'login_name', v_login_name
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_forced_password_change_internal(p_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_profile public.profiles%rowtype; v_at timestamptz := clock_timestamp();
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'SERVICE_ROLE_REQUIRED' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_profile FROM public.profiles WHERE id = p_profile_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PROFILE_NOT_FOUND'; END IF;
  IF v_profile.is_active IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'ACCOUNT_INACTIVE'; END IF;
  IF v_profile.must_change_password IS TRUE THEN
    UPDATE public.profiles SET must_change_password = false, updated_at = v_at WHERE id = p_profile_id;
    INSERT INTO public.audit_logs(user_id, action, table_name, record_id, old_data, new_data, reason, created_at)
    VALUES(p_profile_id, 'COMPLETE_FORCED_PASSWORD_CHANGE', 'profiles', p_profile_id,
      jsonb_build_object('must_change_password', true),
      jsonb_build_object('must_change_password', false, 'completed_at', v_at),
      'ACC06B_AUTH_PASSWORD_UPDATE_CONFIRMED', v_at);
  END IF;
  RETURN jsonb_build_object('success', true, 'profile_id', p_profile_id, 'must_change_password', false);
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_member_hard_delete_auth(p_profile_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_tombstone public.audit_logs%rowtype;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_actor_id AND role = 'ADMIN' AND is_active IS TRUE) THEN
        RAISE EXCEPTION 'ADMIN_REQUIRED' USING ERRCODE = '42501';
    END IF;
    IF p_profile_id = p_actor_id THEN
        RAISE EXCEPTION 'SELF_HARD_DELETE_FORBIDDEN' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_tombstone FROM public.audit_logs
    WHERE action = 'HARD_DELETE_MEMBER_ACCOUNT' AND table_name = 'profiles' AND record_id = p_profile_id
    ORDER BY created_at DESC, id DESC LIMIT 1 FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'RECOVERY_TOMBSTONE_REQUIRED' USING ERRCODE = '22023';
    END IF;
    IF EXISTS (SELECT 1 FROM public.profiles WHERE id = p_profile_id)
       OR EXISTS (SELECT 1 FROM auth.users WHERE id = p_profile_id) THEN
        RAISE EXCEPTION 'CLEANUP_NOT_COMPLETE' USING ERRCODE = '23503';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.audit_logs
        WHERE action = 'HARD_DELETE_MEMBER_AUTH_COMPLETED' AND table_name = 'profiles' AND record_id = p_profile_id) THEN
        INSERT INTO public.audit_logs(user_id,action,table_name,record_id,old_data,new_data,reason)
        VALUES(p_actor_id,'HARD_DELETE_MEMBER_AUTH_COMPLETED','profiles',p_profile_id,NULL,
            jsonb_build_object('auth_user_id',p_profile_id,'player_id',v_tombstone.old_data->'player_id',
                'tombstone_id',v_tombstone.id,'auth_cleanup_status','COMPLETED',
                'auth_cleanup_completed_at',clock_timestamp()),v_tombstone.reason);
    END IF;
    RETURN jsonb_build_object('success',true,'profile_id',p_profile_id,
        'player_id',v_tombstone.old_data->'player_id','auth_cleanup_status','COMPLETED');
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_my_password_change()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  update public.profiles
  set must_change_password = false
  where id = v_user_id
    and is_active = true;

  if not found then
    raise exception 'PROFILE_NOT_FOUND_OR_INACTIVE';
  end if;

  return jsonb_build_object(
    'success', true,
    'must_change_password', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_match_by_opponent(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid;
  v_actor_player_id uuid;
  v_match public.matches%rowtype;
  v_creator_player_id uuid;
  v_creator_team text;
  v_actor_team text;
  v_result jsonb;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
  perform pg_advisory_xact_lock(726184501);

  v_actor := auth.uid();

  if v_actor is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select pr.player_id
  into v_actor_player_id
  from public.profiles pr
  join public.players p
    on p.id = pr.player_id
  where pr.id = v_actor
    and pr.role = 'MEMBER'
    and pr.is_active = true
    and p.player_type = 'CLUB'
    and p.status = 'ACTIVE';

  if not found
     or v_actor_player_id is null then
    raise exception 'ACTIVE_MEMBER_PLAYER_REQUIRED';
  end if;

  if p_match_id is null then
    raise exception 'MATCH_ID_REQUIRED';
  end if;

  select *
  into v_match
  from public.matches
  where id = p_match_id
  for update;

  if not found then
    raise exception 'MATCH_NOT_FOUND';
  end if;

  if v_match.status <> 'PENDING' then
    raise exception 'MATCH_NOT_PENDING';
  end if;

  -- P1.2b hardening:
  -- Once rejected, creator must edit/resubmit first.
  if v_match.opponent_rejected_by is not null then
    raise exception
      'MATCH_REJECTED_WAITING_CREATOR_RESUBMIT';
  end if;

  if v_match.match_type not in (
    'CLUB_RATED',
    'FRIENDLY_RATED'
  ) then
    raise exception
      'OPPONENT_CONFIRMATION_NOT_ALLOWED_FOR_MATCH_TYPE';
  end if;

  if v_match.tournament_id is not null
     or v_match.league_id is not null then
    raise exception
      'OPPONENT_CONFIRMATION_REQUIRES_STANDARD_MATCH';
  end if;

  if v_match.created_by = v_actor then
    raise exception 'CREATOR_CANNOT_CONFIRM';
  end if;

  select
    (al.new_data ->> 'member_player_id')::uuid
  into v_creator_player_id
  from public.audit_logs al
  where al.record_id = p_match_id
    and al.table_name = 'matches'
    and al.action = 'CREATE_MY_PENDING_MATCH'
    and al.user_id = v_match.created_by
  order by al.created_at asc
  limit 1;

  if not found
     or v_creator_player_id is null then
    raise exception 'MEMBER_CREATED_MATCH_REQUIRED';
  end if;

  select mp.team
  into v_creator_team
  from public.match_players mp
  where mp.match_id = p_match_id
    and mp.player_id = v_creator_player_id;

  if not found then
    raise exception 'CREATOR_PLAYER_NOT_IN_MATCH';
  end if;

  select mp.team
  into v_actor_team
  from public.match_players mp
  where mp.match_id = p_match_id
    and mp.player_id = v_actor_player_id;

  if not found then
    raise exception 'CONFIRMER_NOT_IN_MATCH';
  end if;

  if v_actor_team = v_creator_team then
    raise exception 'CREATOR_TEAM_CANNOT_CONFIRM';
  end if;

  v_result :=
    public._approve_match_internal(
      p_match_id,
      public._get_active_rating_version(),
      v_actor,
      v_actor
    );

  return
    v_result ||
    jsonb_build_object(
      'confirmed_at',
      (
        select opponent_confirmed_at
        from public.matches
        where id = p_match_id
      )
    );
end;
$function$

