CREATE OR REPLACE FUNCTION public.create_my_pending_match(p_played_at timestamp with time zone, p_match_type text, p_score_mode text, p_team_a_score integer, p_team_b_score integer, p_team_a_player_1 uuid, p_team_a_player_2 uuid, p_team_b_player_1 uuid, p_team_b_player_2 uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_actor uuid;
    v_profile_role text;
    v_profile_active boolean;
    v_my_player_id uuid;

    v_match_id uuid;
    v_match_number integer;

    v_found_count integer;
    v_active_count integer;
    v_distinct_count integer;
BEGIN
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    PERFORM pg_advisory_xact_lock(726184501);

    v_actor := auth.uid();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'AUTH_REQUIRED';
    END IF;

    SELECT
        p.role,
        p.is_active,
        p.player_id
    INTO
        v_profile_role,
        v_profile_active,
        v_my_player_id
    FROM public.profiles p
    WHERE p.id = v_actor;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PROFILE_NOT_FOUND';
    END IF;

    IF coalesce(v_profile_active, false) = false THEN
        RAISE EXCEPTION 'ACCOUNT_INACTIVE';
    END IF;

    IF upper(coalesce(v_profile_role, '')) <> 'MEMBER' THEN
        RAISE EXCEPTION 'MEMBER_ROLE_REQUIRED';
    END IF;

    IF v_my_player_id IS NULL THEN
        RAISE EXCEPTION 'PLAYER_LINK_REQUIRED';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.players p
        WHERE p.id = v_my_player_id
          AND p.status = 'ACTIVE'
          AND p.player_type = 'CLUB'
    ) THEN
        RAISE EXCEPTION 'MEMBER_PLAYER_INVALID';
    END IF;

    IF p_played_at IS NULL THEN
        RAISE EXCEPTION 'PLAYED_AT_REQUIRED';
    END IF;

    IF p_match_type IS NULL
       OR btrim(p_match_type) = '' THEN
        RAISE EXCEPTION 'MATCH_TYPE_REQUIRED';
    END IF;

    -- P1: MEMBER không được tạo Competition / SELF_REPORTED.
    IF p_match_type NOT IN (
        'CLUB_RATED',
        'FRIENDLY_RATED',
        'TRAINING'
    ) THEN
        RAISE EXCEPTION
            'MEMBER_MATCH_TYPE_NOT_ALLOWED: %',
            p_match_type;
    END IF;

    IF p_score_mode NOT IN (
        'POINTS',
        'RESULT'
    ) THEN
        RAISE EXCEPTION
            'INVALID_SCORE_MODE: %',
            p_score_mode;
    END IF;

    IF p_team_a_score IS NULL
       OR p_team_b_score IS NULL THEN
        RAISE EXCEPTION 'SCORE_REQUIRED';
    END IF;

    IF p_team_a_score < 0
       OR p_team_b_score < 0 THEN
        RAISE EXCEPTION 'NEGATIVE_SCORE_NOT_ALLOWED';
    END IF;

    IF p_score_mode = 'POINTS'
       AND (p_team_a_score + p_team_b_score) <= 0 THEN
        RAISE EXCEPTION 'POINTS_SCORE_MUST_HAVE_RESULT';
    END IF;

    IF p_score_mode = 'RESULT'
       AND p_team_a_score = 0
       AND p_team_b_score = 0 THEN
        RAISE EXCEPTION 'RESULT_SCORE_MUST_HAVE_WINNER';
    END IF;

    IF p_score_mode = 'RESULT'
       AND (
            p_team_a_score NOT IN (0, 1)
            OR p_team_b_score NOT IN (0, 1)
       ) THEN
        RAISE EXCEPTION 'RESULT_SCORE_MUST_BE_0_OR_1';
    END IF;

    IF p_team_a_player_1 IS NULL
       OR p_team_a_player_2 IS NULL
       OR p_team_b_player_1 IS NULL
       OR p_team_b_player_2 IS NULL THEN
        RAISE EXCEPTION 'FOUR_PLAYERS_REQUIRED';
    END IF;

    SELECT count(DISTINCT x)
    INTO v_distinct_count
    FROM unnest(
        ARRAY[
            p_team_a_player_1,
            p_team_a_player_2,
            p_team_b_player_1,
            p_team_b_player_2
        ]::uuid[]
    ) AS t(x);

    IF v_distinct_count <> 4 THEN
        RAISE EXCEPTION 'PLAYERS_MUST_BE_DISTINCT';
    END IF;

    IF NOT (
        v_my_player_id = p_team_a_player_1
        OR v_my_player_id = p_team_a_player_2
        OR v_my_player_id = p_team_b_player_1
        OR v_my_player_id = p_team_b_player_2
    ) THEN
        RAISE EXCEPTION 'MEMBER_MUST_PARTICIPATE';
    END IF;

    SELECT count(*)
    INTO v_found_count
    FROM public.players p
    WHERE p.id = ANY(
        ARRAY[
            p_team_a_player_1,
            p_team_a_player_2,
            p_team_b_player_1,
            p_team_b_player_2
        ]::uuid[]
    );

    IF v_found_count <> 4 THEN
        RAISE EXCEPTION 'PLAYER_NOT_FOUND';
    END IF;

    SELECT count(*)
    INTO v_active_count
    FROM public.players p
    WHERE p.id = ANY(
        ARRAY[
            p_team_a_player_1,
            p_team_a_player_2,
            p_team_b_player_1,
            p_team_b_player_2
        ]::uuid[]
    )
      AND p.status = 'ACTIVE';

    IF v_active_count <> 4 THEN
        RAISE EXCEPTION 'ALL_PLAYERS_MUST_BE_ACTIVE';
    END IF;

    SELECT coalesce(max(m.match_number), 0) + 1
    INTO v_match_number
    FROM public.matches m
    WHERE m.match_number IS NOT NULL;

    INSERT INTO public.matches (
        played_at,
        match_number,
        match_type,
        score_mode,
        team_a_score,
        team_b_score,
        status,
        invalid_reason,
        tournament_id,
        league_id,
        notes,
        created_by,
        created_at,
        updated_at,
        replaces_match_id
    )
    VALUES (
        p_played_at,
        v_match_number,
        p_match_type,
        p_score_mode,
        p_team_a_score,
        p_team_b_score,
        'PENDING',
        NULL,
        NULL,
        NULL,
        nullif(btrim(p_notes), ''),
        v_actor,
        now(),
        now(),
        NULL
    )
    RETURNING id
    INTO v_match_id;

    INSERT INTO public.match_players (
        match_id,
        player_id,
        team,
        partner_player_id,
        created_at
    )
    VALUES
    (
        v_match_id,
        p_team_a_player_1,
        'A',
        p_team_a_player_2,
        now()
    ),
    (
        v_match_id,
        p_team_a_player_2,
        'A',
        p_team_a_player_1,
        now()
    ),
    (
        v_match_id,
        p_team_b_player_1,
        'B',
        p_team_b_player_2,
        now()
    ),
    (
        v_match_id,
        p_team_b_player_2,
        'B',
        p_team_b_player_1,
        now()
    );

    INSERT INTO public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason,
        created_at
    )
    VALUES (
        v_actor,
        'CREATE_MY_PENDING_MATCH',
        'matches',
        v_match_id,
        NULL,
        jsonb_build_object(
            'match_number', v_match_number,
            'played_at', p_played_at,
            'match_type', p_match_type,
            'score_mode', p_score_mode,
            'team_a_score', p_team_a_score,
            'team_b_score', p_team_b_score,
            'team_a', jsonb_build_array(
                p_team_a_player_1,
                p_team_a_player_2
            ),
            'team_b', jsonb_build_array(
                p_team_b_player_1,
                p_team_b_player_2
            ),
            'member_player_id', v_my_player_id,
            'status', 'PENDING',
            'engine', 'MEMBER_PENDING_MATCH_V1_P1'
        ),
        'Thành viên tạo trận và gửi chờ duyệt',
        now()
    );

    RETURN jsonb_build_object(
        'success', true,
        'match_id', v_match_id,
        'match_number', v_match_number,
        'status', 'PENDING',
        'created_by', v_actor,
        'member_player_id', v_my_player_id,
        'players_set', 4
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_my_tournament_registration(p_tournament_id uuid, p_event_name text, p_partner_player_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_profile public.profiles%rowtype;
    v_tournament public.tournaments%rowtype;
    v_player public.players%rowtype;
    v_partner public.players%rowtype;
    v_registration public.tournament_registrations%rowtype;
    v_player_id uuid;
    v_event_name text;
    v_fee_due numeric;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    v_actor := auth.uid();

    if v_actor is null then
        raise exception 'AUTH_REQUIRED';
    end if;

    select *
    into v_profile
    from public.profiles
    where id = v_actor;

    if not found then
        raise exception 'PROFILE_NOT_FOUND';
    end if;

    if v_profile.is_active is not true then
        raise exception 'ACCOUNT_INACTIVE';
    end if;

    if upper(coalesce(v_profile.role, '')) <> 'MEMBER' then
        raise exception 'MEMBER_ROLE_REQUIRED';
    end if;

    v_player_id := v_profile.player_id;

    if v_player_id is null then
        raise exception 'PLAYER_LINK_REQUIRED';
    end if;

    if p_tournament_id is null then
        raise exception 'TOURNAMENT_ID_REQUIRED';
    end if;

    v_event_name := nullif(btrim(p_event_name), '');

    if v_event_name is null then
        raise exception 'EVENT_NAME_REQUIRED';
    end if;

    if char_length(v_event_name) > 200 then
        raise exception 'EVENT_NAME_TOO_LONG';
    end if;

    select *
    into v_tournament
    from public.tournaments
    where id = p_tournament_id
    for share;

    if not found then
        raise exception 'TOURNAMENT_NOT_FOUND';
    end if;

    if v_tournament.status <> 'MO_DANG_KY' then
        raise exception
            'TOURNAMENT_NOT_OPEN_FOR_MEMBER_REGISTRATION: %',
            v_tournament.status;
    end if;

    select *
    into v_player
    from public.players
    where id = v_player_id;

    if not found then
        raise exception 'PLAYER_NOT_FOUND';
    end if;

    if upper(coalesce(v_player.status, '')) <> 'ACTIVE' then
        raise exception 'PLAYER_INACTIVE';
    end if;

    if upper(coalesce(v_player.player_type, '')) <> 'CLUB' then
        raise exception 'CLUB_PLAYER_REQUIRED';
    end if;

    if p_partner_player_id is not null then
        if p_partner_player_id = v_player_id then
            raise exception 'PARTNER_CANNOT_BE_SELF';
        end if;

        select *
        into v_partner
        from public.players
        where id = p_partner_player_id;

        if not found then
            raise exception 'PARTNER_NOT_FOUND';
        end if;

        if upper(coalesce(v_partner.status, '')) <> 'ACTIVE' then
            raise exception 'PARTNER_INACTIVE';
        end if;
    end if;

    v_fee_due :=
        coalesce(
            v_tournament.registration_fee,
            0
        );

    if v_fee_due < 0 then
        raise exception 'FEE_DUE_MUST_BE_NONNEGATIVE';
    end if;

    perform pg_advisory_xact_lock(
        hashtextextended(
            p_tournament_id::text || '|' ||
            lower(v_event_name),
            0
        )
    );

    if exists (
        select 1
        from public.tournament_registrations tr
        where tr.tournament_id = p_tournament_id
          and lower(btrim(tr.event_name)) =
              lower(v_event_name)
          and tr.status <> 'HUY'
          and (
              tr.player_id = v_player_id
              or tr.partner_player_id = v_player_id
          )
    ) then
        raise exception
            'PLAYER_ALREADY_REGISTERED_FOR_EVENT';
    end if;

    if p_partner_player_id is not null
       and exists (
            select 1
            from public.tournament_registrations tr
            where tr.tournament_id = p_tournament_id
              and lower(btrim(tr.event_name)) =
                  lower(v_event_name)
              and tr.status <> 'HUY'
              and (
                  tr.player_id = p_partner_player_id
                  or tr.partner_player_id =
                      p_partner_player_id
              )
       )
    then
        raise exception
            'PARTNER_ALREADY_REGISTERED_FOR_EVENT';
    end if;

    insert into public.tournament_registrations (
        tournament_id,
        player_id,
        event_name,
        partner_player_id,
        fee_due,
        status
    )
    values (
        p_tournament_id,
        v_player_id,
        v_event_name,
        p_partner_player_id,
        v_fee_due,
        'DANG_KY'
    )
    returning *
    into v_registration;

    insert into public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason
    )
    values (
        v_actor,
        'CREATE_MY_TOURNAMENT_REGISTRATION',
        'tournament_registrations',
        v_registration.id,
        null,
        to_jsonb(v_registration),
        'Thành viên tự đăng ký tham gia giải'
    );

    return jsonb_build_object(
        'success', true,
        'registration_id', v_registration.id,
        'tournament_id', v_registration.tournament_id,
        'player_id', v_registration.player_id,
        'event_name', v_registration.event_name,
        'partner_player_id',
            v_registration.partner_player_id,
        'fee_due', v_registration.fee_due,
        'status', v_registration.status,
        'created_at', v_registration.created_at
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_pending_match(p_played_at timestamp with time zone, p_match_number integer DEFAULT NULL::integer, p_match_type text DEFAULT 'CLUB_RATED'::text, p_score_mode text DEFAULT 'POINTS'::text, p_team_a_score integer DEFAULT 0, p_team_b_score integer DEFAULT 0, p_tournament_id uuid DEFAULT NULL::uuid, p_league_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id uuid;
    v_role text;
    v_is_active boolean;

    v_match_id uuid;
    v_match_number integer;

    v_tournament_status text;
    v_league_status text;
BEGIN
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    PERFORM pg_advisory_xact_lock(726184501);

    IF p_played_at IS NULL THEN
        RAISE EXCEPTION 'played_at không được NULL';
    END IF;

    IF p_match_type IS NULL
       OR btrim(p_match_type) = '' THEN
        RAISE EXCEPTION 'match_type không được để trống';
    END IF;

    IF p_score_mode IS NULL
       OR btrim(p_score_mode) = '' THEN
        RAISE EXCEPTION 'score_mode không được để trống';
    END IF;

    IF p_team_a_score IS NULL
       OR p_team_b_score IS NULL THEN
        RAISE EXCEPTION 'Tỷ số không được NULL';
    END IF;

    IF p_team_a_score < 0
       OR p_team_b_score < 0 THEN
        RAISE EXCEPTION 'Tỷ số không được âm';
    END IF;

    IF p_match_number IS NOT NULL
       AND p_match_number <= 0 THEN
        RAISE EXCEPTION 'Số trận phải lớn hơn 0';
    END IF;

    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION
            'Bạn chưa đăng nhập hoặc phiên đăng nhập không hợp lệ';
    END IF;

    SELECT role, is_active
    INTO v_role, v_is_active
    FROM public.profiles
    WHERE id = v_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Không tìm thấy hồ sơ người dùng';
    END IF;

    IF coalesce(v_is_active, false) = false THEN
        RAISE EXCEPTION 'Tài khoản đã bị vô hiệu hóa';
    END IF;

    IF v_role <> 'ADMIN' THEN
        RAISE EXCEPTION 'Chỉ ADMIN mới được tạo trận đấu';
    END IF;

    IF p_match_type NOT IN (
        'TOURNAMENT',
        'LEAGUE',
        'CLUB_RATED',
        'FRIENDLY_RATED',
        'TRAINING'
    ) THEN
        RAISE EXCEPTION
            'match_type không được phép tạo mới: %',
            p_match_type;
    END IF;

    IF p_score_mode NOT IN ('POINTS', 'RESULT') THEN
        RAISE EXCEPTION
            'score_mode không hợp lệ: %',
            p_score_mode;
    END IF;

    IF p_score_mode = 'RESULT'
       AND (
            p_team_a_score NOT IN (0, 1)
            OR p_team_b_score NOT IN (0, 1)
       ) THEN
        RAISE EXCEPTION
            'Trận RESULT chỉ chấp nhận score 0 hoặc 1';
    END IF;

    IF p_match_type = 'TOURNAMENT' THEN

        IF p_tournament_id IS NULL
           OR p_league_id IS NOT NULL THEN
            RAISE EXCEPTION
                'TOURNAMENT_REQUIRES_TOURNAMENT_ID_ONLY';
        END IF;

        SELECT t.status
        INTO v_tournament_status
        FROM public.tournaments t
        WHERE t.id = p_tournament_id
        FOR SHARE;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'Không tìm thấy giải đấu: %',
                p_tournament_id;
        END IF;

        IF v_tournament_status NOT IN (
            'DU_KIEN',
            'MO_DANG_KY',
            'DANG_DIEN_RA'
        ) THEN
            RAISE EXCEPTION
                'Không thể gắn trận mới vào giải có trạng thái %',
                v_tournament_status;
        END IF;

    ELSIF p_match_type = 'LEAGUE' THEN

        IF p_league_id IS NULL
           OR p_tournament_id IS NOT NULL THEN
            RAISE EXCEPTION
                'LEAGUE_REQUIRES_LEAGUE_ID_ONLY';
        END IF;

        SELECT l.status
        INTO v_league_status
        FROM public.leagues l
        WHERE l.id = p_league_id
        FOR SHARE;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'LEAGUE_NOT_FOUND: %',
                p_league_id;
        END IF;

        IF v_league_status NOT IN (
            'DU_KIEN',
            'DANG_DIEN_RA'
        ) THEN
            RAISE EXCEPTION
                'LEAGUE_STATUS_NOT_ATTACHABLE: %',
                v_league_status;
        END IF;

    ELSE

        IF p_tournament_id IS NOT NULL
           OR p_league_id IS NOT NULL THEN
            RAISE EXCEPTION
                'STANDARD_MATCH_CANNOT_HAVE_COMPETITION_ID';
        END IF;

    END IF;

    IF p_match_number IS NULL THEN
        SELECT coalesce(max(m.match_number), 0) + 1
        INTO v_match_number
        FROM public.matches m
        WHERE m.match_number IS NOT NULL;
    ELSE
        v_match_number := p_match_number;
    END IF;

    INSERT INTO public.matches (
        played_at,
        match_number,
        match_type,
        score_mode,
        team_a_score,
        team_b_score,
        status,
        invalid_reason,
        tournament_id,
        league_id,
        notes,
        created_by,
        created_at,
        updated_at,
        replaces_match_id
    )
    VALUES (
        p_played_at,
        v_match_number,
        p_match_type,
        p_score_mode,
        p_team_a_score,
        p_team_b_score,
        'PENDING',
        NULL,
        p_tournament_id,
        p_league_id,
        nullif(btrim(p_notes), ''),
        v_user_id,
        now(),
        now(),
        NULL
    )
    RETURNING id INTO v_match_id;

    INSERT INTO public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason,
        created_at
    )
    VALUES (
        v_user_id,
        'CREATE_PENDING_MATCH',
        'matches',
        v_match_id,
        NULL,
        jsonb_build_object(
            'played_at', p_played_at,
            'match_number', v_match_number,
            'match_type', p_match_type,
            'score_mode', p_score_mode,
            'team_a_score', p_team_a_score,
            'team_b_score', p_team_b_score,
            'status', 'PENDING',
            'tournament_id', p_tournament_id,
            'league_id', p_league_id,
            'notes', nullif(btrim(p_notes), ''),
            'created_by', v_user_id,
            'engine', 'CREATE_PENDING_MATCH_P1'
        ),
        'Tạo trận PENDING mới',
        now()
    );

    RETURN jsonb_build_object(
        'success', true,
        'match_id', v_match_id,
        'status', 'PENDING',
        'played_at', p_played_at,
        'match_number', v_match_number,
        'match_type', p_match_type,
        'score_mode', p_score_mode,
        'team_a_score', p_team_a_score,
        'team_b_score', p_team_b_score,
        'tournament_id', p_tournament_id,
        'league_id', p_league_id,
        'notes', nullif(btrim(p_notes), '')
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_player(p_full_name text, p_player_type text DEFAULT 'CLUB'::text, p_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_initial_rating numeric DEFAULT NULL::numeric, p_joined_at date DEFAULT NULL::date, p_date_of_birth date DEFAULT NULL::date, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_name text;
    v_type text;
    v_player public.players%rowtype;

    v_default_rating numeric;
    v_min_rating numeric;
    v_max_rating numeric;
    v_initial_rating numeric;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    v_actor := auth.uid();

    if v_actor is null then
        raise exception 'AUTH_REQUIRED';
    end if;

    if not exists (
        select 1
        from public.profiles p
        where p.id = v_actor
          and (
              upper(coalesce(p.role, '')) = 'ADMIN'
              or coalesce(p.can_manage_players, false)
          )
          and p.is_active = true
    ) then
        raise exception 'PLAYER_MANAGEMENT_PERMISSION_REQUIRED';
    end if;

    select
        rs.initial_rating,
        rs.min_rating,
        rs.max_rating
    into
        v_default_rating,
        v_min_rating,
        v_max_rating
    from public.rating_settings rs
    where rs.is_active = true;

    if not found then
        raise exception 'ACTIVE_RATING_SETTINGS_REQUIRED';
    end if;

    v_name :=
        nullif(
            trim(p_full_name),
            ''
        );

    if v_name is null then
        raise exception 'PLAYER_NAME_REQUIRED';
    end if;

    v_type :=
        upper(
            trim(
                coalesce(
                    p_player_type,
                    ''
                )
            )
        );

    if v_type not in (
        'CLUB',
        'GUEST'
    ) then
        raise exception 'INVALID_PLAYER_TYPE';
    end if;

    v_initial_rating :=
        coalesce(
            p_initial_rating,
            v_default_rating
        );

    if v_initial_rating < v_min_rating
       or v_initial_rating > v_max_rating then
        raise exception 'INVALID_INITIAL_RATING';
    end if;

    if p_date_of_birth is not null
       and p_date_of_birth > current_date then
        raise exception 'INVALID_DATE_OF_BIRTH';
    end if;

    insert into public.players (
        full_name,
        player_type,
        phone,
        email,
        initial_rating,
        current_rating,
        status,
        joined_at,
        date_of_birth,
        notes
    )
    values (
        v_name,
        v_type,
        nullif(trim(p_phone), ''),
        nullif(trim(p_email), ''),
        v_initial_rating,
        v_initial_rating,
        'ACTIVE',
        p_joined_at,
        p_date_of_birth,
        nullif(trim(p_notes), '')
    )
    returning *
    into v_player;

    insert into public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason
    )
    values (
        v_actor,
        'CREATE_PLAYER',
        'players',
        v_player.id,
        null,
        to_jsonb(v_player),
        'PLAYER_WRITE_API_ACTIVE_RATING_SETTINGS'
    );

    return jsonb_build_object(
        'success', true,
        'player_id', v_player.id,
        'full_name', v_player.full_name,
        'player_type', v_player.player_type,
        'status', v_player.status,
        'initial_rating', v_player.initial_rating,
        'current_rating', v_player.current_rating,
        'date_of_birth', v_player.date_of_birth
    );
end;
$function$

