CREATE OR REPLACE FUNCTION public.create_tournament_expense(p_tournament_id uuid, p_amount numeric, p_category text, p_description text, p_expense_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid;
  v_profile public.profiles%rowtype;
  v_tournament public.tournaments%rowtype;
  v_expense public.tournament_expenses%rowtype;

  v_category text;
  v_description text;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
  -- ----------------------------------------------------------
  -- AUTH
  -- ----------------------------------------------------------
  v_actor := auth.uid();

  if v_actor is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select *
  into v_profile
  from public.profiles
  where id = v_actor;

  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  if coalesce(v_profile.is_active, false) = false then
    raise exception 'PROFILE_INACTIVE';
  end if;

  if upper(coalesce(v_profile.role, '')) <> 'ADMIN'
     and coalesce(v_profile.can_manage_tournaments, false) = false then
    raise exception
      'TOURNAMENT_MANAGEMENT_PERMISSION_REQUIRED';
  end if;


  -- ----------------------------------------------------------
  -- INPUT
  -- ----------------------------------------------------------
  if p_tournament_id is null then
    raise exception 'TOURNAMENT_ID_REQUIRED';
  end if;

  if p_amount is null then
    raise exception 'EXPENSE_AMOUNT_REQUIRED';
  end if;

  if p_amount <= 0 then
    raise exception
      'EXPENSE_AMOUNT_MUST_BE_POSITIVE';
  end if;

  if p_expense_date is null then
    raise exception 'EXPENSE_DATE_REQUIRED';
  end if;

  v_category :=
    nullif(
      btrim(coalesce(p_category, '')),
      ''
    );

  if v_category is null then
    raise exception 'EXPENSE_CATEGORY_REQUIRED';
  end if;

  if char_length(v_category) > 100 then
    raise exception 'EXPENSE_CATEGORY_TOO_LONG';
  end if;

  v_description :=
    nullif(
      btrim(coalesce(p_description, '')),
      ''
    );

  if v_description is null then
    raise exception 'EXPENSE_DESCRIPTION_REQUIRED';
  end if;

  if char_length(v_description) > 1000 then
    raise exception 'EXPENSE_DESCRIPTION_TOO_LONG';
  end if;


  -- ----------------------------------------------------------
  -- TOURNAMENT
  -- ----------------------------------------------------------
  select *
  into v_tournament
  from public.tournaments
  where id = p_tournament_id
  for update;

  if not found then
    raise exception 'TOURNAMENT_NOT_FOUND';
  end if;

  if upper(v_tournament.status) = 'HUY' then
    raise exception 'TOURNAMENT_CANCELLED';
  end if;

  if upper(v_tournament.status) = 'DA_QUYET_TOAN' then
    raise exception 'TOURNAMENT_ALREADY_SETTLED';
  end if;


  -- ----------------------------------------------------------
  -- INSERT EXPENSE
  -- ----------------------------------------------------------
  insert into public.tournament_expenses (
    tournament_id,
    expense_date,
    category,
    description,
    amount,
    created_by
  )
  values (
    p_tournament_id,
    p_expense_date,
    v_category,
    v_description,
    p_amount,
    v_actor
  )
  returning *
  into v_expense;


  -- ----------------------------------------------------------
  -- AUDIT
  -- ----------------------------------------------------------
  insert into public.audit_logs (
    user_id,
    action,
    table_name,
    record_id,
    old_data,
    new_data,
    reason,
    created_at
  )
  values (
    v_actor,
    'CREATE_TOURNAMENT_EXPENSE',
    'tournament_expenses',
    v_expense.id,
    null,
    jsonb_build_object(
      'id', v_expense.id,
      'tournament_id', v_expense.tournament_id,
      'expense_date', v_expense.expense_date,
      'category', v_expense.category,
      'description', v_expense.description,
      'amount', v_expense.amount,
      'created_by', v_expense.created_by,
      'engine', 'TOURNAMENT_EXPENSE_V1'
    ),
    v_description,
    now()
  );


  -- ----------------------------------------------------------
  -- RESULT
  -- ----------------------------------------------------------
  return jsonb_build_object(
    'ok', true,
    'expense_id', v_expense.id,
    'tournament_id', v_expense.tournament_id,
    'expense_date', v_expense.expense_date,
    'category', v_expense.category,
    'description', v_expense.description,
    'amount', v_expense.amount,
    'created_by', v_expense.created_by
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_payment(p_registration_id uuid, p_amount numeric, p_paid_at timestamp with time zone DEFAULT now(), p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_uid uuid;

    v_profile public.profiles%rowtype;

    v_registration
        public.tournament_registrations%rowtype;

    v_tournament
        public.tournaments%rowtype;

    v_payment
        public.tournament_payments%rowtype;

    v_amount numeric;
    v_paid_before numeric := 0;
    v_paid_after numeric := 0;
    v_remaining_before numeric := 0;
    v_remaining_after numeric := 0;

    v_note text;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    /* --------------------------------------------------------
       Authentication / authorization
       -------------------------------------------------------- */

    v_uid := auth.uid();

    if v_uid is null then
        raise exception 'AUTH_REQUIRED';
    end if;

    select *
    into v_profile
    from public.profiles
    where id = v_uid;

    if not found then
        raise exception 'PROFILE_NOT_FOUND';
    end if;

    if coalesce(
        v_profile.is_active,
        false
    ) = false then
        raise exception 'PROFILE_INACTIVE';
    end if;

    /*
     * V1J.2:
     * Thu phí dựa trên permission,
     * không phụ thuộc trực tiếp vào role ADMIN.
     */
    if upper(coalesce(v_profile.role, '')) <> 'ADMIN'
       and coalesce(v_profile.can_collect_tournament_fee, false) = false then
        raise exception 'TREASURER_PERMISSION_REQUIRED';
    end if;


    /* --------------------------------------------------------
       Input validation
       -------------------------------------------------------- */

    if p_registration_id is null then
        raise exception 'REGISTRATION_ID_REQUIRED';
    end if;

    v_amount := p_amount;

    if v_amount is null then
        raise exception 'PAYMENT_AMOUNT_REQUIRED';
    end if;

    if v_amount <= 0 then
        raise exception 'PAYMENT_AMOUNT_MUST_BE_POSITIVE';
    end if;

    if p_paid_at is null then
        raise exception 'PAID_AT_REQUIRED';
    end if;

    v_note :=
        nullif(
            btrim(
                coalesce(
                    p_note,
                    ''
                )
            ),
            ''
        );


    /* --------------------------------------------------------
       Lock registration.
       Payment and registration-status writers lock this row.
       -------------------------------------------------------- */

    select *
    into v_registration
    from public.tournament_registrations
    where id = p_registration_id
    for update;

    if not found then
        raise exception 'REGISTRATION_NOT_FOUND';
    end if;


    /* --------------------------------------------------------
       Registration state
       -------------------------------------------------------- */

    if upper(v_registration.status) = 'HUY' then
        raise exception 'REGISTRATION_CANCELLED';
    end if;

    if upper(v_registration.status) not in (
        'DANG_KY',
        'DA_XAC_NHAN'
    ) then
        raise exception 'REGISTRATION_NOT_PAYABLE';
    end if;


    /* --------------------------------------------------------
       Tournament lifecycle
       -------------------------------------------------------- */

    select *
    into v_tournament
    from public.tournaments
    where id = v_registration.tournament_id;

    if not found then
        raise exception 'TOURNAMENT_NOT_FOUND';
    end if;

    if upper(v_tournament.status) = 'HUY' then
        raise exception 'TOURNAMENT_CANCELLED';
    end if;

    if upper(v_tournament.status) = 'DA_QUYET_TOAN' then
        raise exception 'TOURNAMENT_ALREADY_SETTLED';
    end if;


    /* --------------------------------------------------------
       Existing payments
       -------------------------------------------------------- */

    select coalesce(
        sum(tp.amount),
        0
    )
    into v_paid_before
    from public.tournament_payments tp
    where tp.registration_id = v_registration.id;

    v_remaining_before :=
        greatest(
            v_registration.fee_due -
            v_paid_before,
            0
        );


    /* --------------------------------------------------------
       Debt guards
       -------------------------------------------------------- */

    if v_registration.fee_due <= 0 then
        raise exception 'REGISTRATION_HAS_NO_FEE_DUE';
    end if;

    if v_remaining_before <= 0 then
        raise exception 'REGISTRATION_ALREADY_PAID_IN_FULL';
    end if;

    if v_amount > v_remaining_before then
        raise exception 'PAYMENT_EXCEEDS_REMAINING_BALANCE';
    end if;


    /* --------------------------------------------------------
       Append-only payment
       -------------------------------------------------------- */

    insert into public.tournament_payments(
        registration_id,
        player_id,
        amount,
        paid_at,
        confirmed_by,
        note
    )
    values (
        v_registration.id,
        v_registration.player_id,
        v_amount,
        p_paid_at,
        v_uid,
        v_note
    )
    returning *
    into v_payment;


    /* --------------------------------------------------------
       Final totals
       -------------------------------------------------------- */

    v_paid_after :=
        v_paid_before +
        v_payment.amount;

    v_remaining_after :=
        greatest(
            v_registration.fee_due -
            v_paid_after,
            0
        );


    /* --------------------------------------------------------
       Audit
       -------------------------------------------------------- */

    insert into public.audit_logs(
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason
    )
    values (
        v_uid,
        'CREATE_TOURNAMENT_PAYMENT',
        'tournament_payments',
        v_payment.id,
        null,
        to_jsonb(v_payment),
        'Thu phí đăng ký giải'
    );


    /* --------------------------------------------------------
       Response
       -------------------------------------------------------- */

    return jsonb_build_object(
        'ok',
        true,

        'payment_id',
        v_payment.id,

        'registration_id',
        v_registration.id,

        'tournament_id',
        v_registration.tournament_id,

        'player_id',
        v_registration.player_id,

        'amount',
        v_payment.amount,

        'fee_due',
        v_registration.fee_due,

        'paid_before',
        v_paid_before,

        'paid_after',
        v_paid_after,

        'remaining_before',
        v_remaining_before,

        'remaining_after',
        v_remaining_after,

        'paid_in_full',
        (
            v_remaining_after = 0
        )
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_registration(p_tournament_id uuid, p_player_id uuid, p_event_name text, p_partner_player_id uuid DEFAULT NULL::uuid, p_fee_due numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_profile public.profiles%rowtype;
    v_tournament public.tournaments%rowtype;
    v_player public.players%rowtype;
    v_partner public.players%rowtype;
    v_registration public.tournament_registrations%rowtype;
    v_event_name text;
    v_fee_due numeric;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    v_actor := auth.uid();

    if v_actor is null then
        raise exception 'AUTH_REQUIRED';
    end if;

    select *
    into v_profile
    from public.profiles
    where id = v_actor;

    if not found then
        raise exception 'PROFILE_NOT_FOUND';
    end if;

    if v_profile.is_active is not true then
        raise exception 'ACCOUNT_INACTIVE';
    end if;

    if upper(coalesce(v_profile.role, '')) <> 'ADMIN'
       and coalesce(v_profile.can_manage_tournaments, false) = false then
        raise exception 'TOURNAMENT_MANAGEMENT_PERMISSION_REQUIRED';
    end if;

    if p_tournament_id is null then
        raise exception 'TOURNAMENT_ID_REQUIRED';
    end if;

    if p_player_id is null then
        raise exception 'PLAYER_ID_REQUIRED';
    end if;

    v_event_name := nullif(btrim(p_event_name), '');

    if v_event_name is null then
        raise exception 'EVENT_NAME_REQUIRED';
    end if;

    if char_length(v_event_name) > 200 then
        raise exception 'EVENT_NAME_TOO_LONG';
    end if;

    select *
    into v_tournament
    from public.tournaments
    where id = p_tournament_id
    for share;

    if not found then
        raise exception 'TOURNAMENT_NOT_FOUND';
    end if;

    if v_tournament.status not in (
        'DU_KIEN',
        'MO_DANG_KY'
    ) then
        raise exception
            'TOURNAMENT_NOT_OPEN_FOR_REGISTRATION: %',
            v_tournament.status;
    end if;

    select *
    into v_player
    from public.players
    where id = p_player_id;

    if not found then
        raise exception 'PLAYER_NOT_FOUND';
    end if;

    if upper(coalesce(v_player.status, '')) <> 'ACTIVE' then
        raise exception 'PLAYER_INACTIVE';
    end if;

    if p_partner_player_id is not null then
        if p_partner_player_id = p_player_id then
            raise exception 'PARTNER_CANNOT_BE_SELF';
        end if;

        select *
        into v_partner
        from public.players
        where id = p_partner_player_id;

        if not found then
            raise exception 'PARTNER_NOT_FOUND';
        end if;

        if upper(coalesce(v_partner.status, '')) <> 'ACTIVE' then
            raise exception 'PARTNER_INACTIVE';
        end if;
    end if;

    v_fee_due :=
        coalesce(
            p_fee_due,
            v_tournament.registration_fee,
            0
        );

    if v_fee_due < 0 then
        raise exception 'FEE_DUE_MUST_BE_NONNEGATIVE';
    end if;

    perform pg_advisory_xact_lock(
        hashtextextended(
            p_tournament_id::text || '|' ||
            lower(v_event_name),
            0
        )
    );

    if exists (
        select 1
        from public.tournament_registrations tr
        where tr.tournament_id = p_tournament_id
          and lower(btrim(tr.event_name)) =
              lower(v_event_name)
          and tr.status <> 'HUY'
          and (
              tr.player_id = p_player_id
              or tr.partner_player_id = p_player_id
          )
    ) then
        raise exception
            'PLAYER_ALREADY_REGISTERED_FOR_EVENT';
    end if;

    if p_partner_player_id is not null
       and exists (
            select 1
            from public.tournament_registrations tr
            where tr.tournament_id = p_tournament_id
              and lower(btrim(tr.event_name)) =
                  lower(v_event_name)
              and tr.status <> 'HUY'
              and (
                  tr.player_id = p_partner_player_id
                  or tr.partner_player_id =
                      p_partner_player_id
              )
       )
    then
        raise exception
            'PARTNER_ALREADY_REGISTERED_FOR_EVENT';
    end if;

    insert into public.tournament_registrations (
        tournament_id,
        player_id,
        event_name,
        partner_player_id,
        fee_due,
        status
    )
    values (
        p_tournament_id,
        p_player_id,
        v_event_name,
        p_partner_player_id,
        v_fee_due,
        'DANG_KY'
    )
    returning *
    into v_registration;

    insert into public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason
    )
    values (
        v_actor,
        'CREATE_TOURNAMENT_REGISTRATION',
        'tournament_registrations',
        v_registration.id,
        null,
        to_jsonb(v_registration),
        'Đăng ký VĐV tham gia giải'
    );

    return jsonb_build_object(
        'success', true,
        'registration_id', v_registration.id,
        'tournament_id', v_registration.tournament_id,
        'player_id', v_registration.player_id,
        'event_name', v_registration.event_name,
        'partner_player_id',
            v_registration.partner_player_id,
        'fee_due', v_registration.fee_due,
        'status', v_registration.status,
        'created_at', v_registration.created_at
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_player_if_unreferenced(p_player_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_actor uuid;
    v_reason text;
    v_player public.players%rowtype;
    v_snapshot jsonb;
    v_reference_total bigint;
    v_tombstone_id uuid;
BEGIN
    v_actor := auth.uid();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE = '42501';
    END IF;

    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.profiles p
        WHERE p.id = v_actor
          AND p.is_active IS TRUE
          AND upper(coalesce(p.role, '')) = 'ADMIN'
    ) THEN
        RAISE EXCEPTION 'ADMIN_REQUIRED' USING ERRCODE = '42501';
    END IF;

    IF p_player_id IS NULL THEN
        RAISE EXCEPTION 'PLAYER_ID_REQUIRED' USING ERRCODE = '22023';
    END IF;

    v_reason := nullif(btrim(p_reason), '');
    IF v_reason IS NULL OR char_length(v_reason) > 1000 THEN
        RAISE EXCEPTION 'REASON_REQUIRED_MAX_1000' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_player
    FROM public.players p
    WHERE p.id = p_player_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PLAYER_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;

    -- Every reference writer now acquires a key-share lock through its FK,
    -- including match_players.partner_player_id added by this migration.
    v_snapshot := public.player_reference_snapshot(v_player.id);
    v_reference_total := (v_snapshot ->> 'reference_total')::bigint;

    IF v_reference_total <> 0 THEN
        RAISE EXCEPTION 'PLAYER_HAS_REFERENCES'
            USING ERRCODE = '23503', DETAIL = v_snapshot::text;
    END IF;

    INSERT INTO public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason
    ) VALUES (
        v_actor,
        'PLAYER_HARD_DELETED',
        'players',
        v_player.id,
        jsonb_build_object(
            'player_id', v_player.id,
            'full_name', v_player.full_name,
            'player_type', v_player.player_type,
            'status', v_player.status,
            'initial_rating', v_player.initial_rating,
            'current_rating', v_player.current_rating
        ),
        jsonb_build_object(
            'hard_deleted', true,
            'inventory_version', v_snapshot ->> 'inventory_version',
            'reference_total', v_reference_total
        ),
        v_reason
    )
    RETURNING id INTO v_tombstone_id;

    DELETE FROM public.players
    WHERE id = v_player.id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PLAYER_DELETE_FAILED' USING ERRCODE = 'P0001';
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'deleted', true,
        'player_id', v_player.id,
        'reason', v_reason,
        'inventory_version', v_snapshot ->> 'inventory_version',
        'tombstone_audit_id', v_tombstone_id
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_match_fund(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_user_id uuid;
    v_role text;
    v_is_active boolean;
    v_can_manage_fund boolean;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;

    -- 1. LẤY USER TỪ JWT
    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Bạn chưa đăng nhập hoặc phiên đăng nhập không hợp lệ';
    end if;


    -- 2. KIỂM TRA PROFILE
    select
        role,
        is_active,
        can_manage_fund
    into
        v_role,
        v_is_active,
        v_can_manage_fund
    from public.profiles
    where id = v_user_id;

    if not found then
        raise exception
            'Không tìm thấy hồ sơ người dùng';
    end if;


    -- 3. KIỂM TRA ACTIVE
    if coalesce(v_is_active, false) = false then
        raise exception
            'Tài khoản đã bị vô hiệu hóa';
    end if;


    -- 4. CHỈ ADMIN ĐƯỢC SINH NGHĨA VỤ QUỸ
    if upper(coalesce(v_role, '')) <> 'ADMIN'
       and coalesce(v_can_manage_fund, false) = false then
        raise exception
            'FUND_MANAGEMENT_PERMISSION_REQUIRED';
    end if;


    -- 5. GỌI INTERNAL FUND ENGINE
    -- actor_user_id luôn lấy từ JWT,
    -- frontend không được tự truyền user_id.
    return public._generate_match_fund_internal(
        p_match_id,
        v_user_id
    );

end;
$function$

