CREATE OR REPLACE FUNCTION public.guard_match_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_workflow text;
begin
  v_workflow := current_setting('app.match_workflow', true);

  if tg_op = 'INSERT' then
    if new.status <> 'PENDING' then
      raise exception 'Match mới bắt buộc phải ở trạng thái PENDING';
    end if;
    if new.invalid_reason is not null then
      raise exception 'Match PENDING mới không được có invalid_reason';
    end if;
    if new.opponent_confirmed_by is not null
       or new.opponent_confirmed_at is not null then
      raise exception 'Match PENDING mới không được có opponent confirmation';
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.status <> 'PENDING' then
      raise exception
        'Không được xóa match có trạng thái %. Chỉ PENDING mới được xóa',
        old.status;
    end if;
    return old;
  end if;

  if old.status = 'PENDING' then
    if new.id is distinct from old.id then
      raise exception 'Không được thay đổi id của match PENDING';
    end if;
    if new.created_by is distinct from old.created_by then
      raise exception 'Không được thay đổi created_by của match PENDING';
    end if;
    if new.created_at is distinct from old.created_at then
      raise exception 'Không được thay đổi created_at của match PENDING';
    end if;
    if new.replaces_match_id is distinct from old.replaces_match_id then
      raise exception 'Không được thay đổi replaces_match_id của match PENDING';
    end if;

    if new.status = 'PENDING' then
      if new.invalid_reason is distinct from old.invalid_reason then
        raise exception
          'Không được thay đổi invalid_reason trực tiếp khi match đang PENDING';
      end if;
      if new.opponent_confirmed_by is distinct from old.opponent_confirmed_by
         or new.opponent_confirmed_at is distinct from old.opponent_confirmed_at then
        raise exception
          'Không được ghi opponent confirmation khi match vẫn PENDING';
      end if;
      return new;
    end if;

    if new.status = 'APPROVED'
       and v_workflow = 'APPROVE_MATCH' then
      if new.id is distinct from old.id
         or new.played_at is distinct from old.played_at
         or new.match_number is distinct from old.match_number
         or new.match_type is distinct from old.match_type
         or new.score_mode is distinct from old.score_mode
         or new.team_a_score is distinct from old.team_a_score
         or new.team_b_score is distinct from old.team_b_score
         or new.tournament_id is distinct from old.tournament_id
         or new.league_id is distinct from old.league_id
         or new.notes is distinct from old.notes
         or new.created_by is distinct from old.created_by
         or new.created_at is distinct from old.created_at
         or new.replaces_match_id is distinct from old.replaces_match_id then
        raise exception
          'APPROVE không được đồng thời thay đổi dữ liệu nguồn của match PENDING';
      end if;
      return new;
    end if;

    if new.status = 'INVALID'
       and v_workflow = 'REJECT_MATCH' then
      if new.id is distinct from old.id
         or new.played_at is distinct from old.played_at
         or new.match_number is distinct from old.match_number
         or new.match_type is distinct from old.match_type
         or new.score_mode is distinct from old.score_mode
         or new.team_a_score is distinct from old.team_a_score
         or new.team_b_score is distinct from old.team_b_score
         or new.tournament_id is distinct from old.tournament_id
         or new.league_id is distinct from old.league_id
         or new.notes is distinct from old.notes
         or new.created_by is distinct from old.created_by
         or new.created_at is distinct from old.created_at
         or new.replaces_match_id is distinct from old.replaces_match_id
         or new.opponent_confirmed_by is distinct from old.opponent_confirmed_by
         or new.opponent_confirmed_at is distinct from old.opponent_confirmed_at then
        raise exception
          'REJECT không được đồng thời thay đổi dữ liệu nguồn của match PENDING';
      end if;
      if new.invalid_reason is null or btrim(new.invalid_reason) = '' then
        raise exception 'REJECT bắt buộc phải có lý do';
      end if;
      return new;
    end if;

    raise exception
      'Không được chuyển match từ PENDING sang % bằng UPDATE trực tiếp',
      new.status;
  end if;

  if old.status = 'APPROVED' then
    if new.status = 'VOIDED'
       and v_workflow = 'VOID_MATCH' then
      if new.id is distinct from old.id
         or new.played_at is distinct from old.played_at
         or new.match_number is distinct from old.match_number
         or new.match_type is distinct from old.match_type
         or new.score_mode is distinct from old.score_mode
         or new.team_a_score is distinct from old.team_a_score
         or new.team_b_score is distinct from old.team_b_score
         or new.tournament_id is distinct from old.tournament_id
         or new.league_id is distinct from old.league_id
         or new.notes is distinct from old.notes
         or new.created_by is distinct from old.created_by
         or new.created_at is distinct from old.created_at
         or new.replaces_match_id is distinct from old.replaces_match_id
         or new.opponent_confirmed_by is distinct from old.opponent_confirmed_by
         or new.opponent_confirmed_at is distinct from old.opponent_confirmed_at then
        raise exception
          'VOID không được thay đổi dữ liệu nguồn của match APPROVED';
      end if;
      return new;
    end if;
    raise exception
      'Match APPROVED là bất biến. Hãy VOID rồi tạo replacement';
  end if;

  if old.status = 'VOIDED' then
    raise exception
      'Match VOIDED là lịch sử bất biến và không được sửa trực tiếp';
  end if;
  if old.status = 'INVALID' then
    raise exception
      'Match INVALID là lịch sử bất biến và không được sửa trực tiếp';
  end if;
  raise exception 'Trạng thái match không được hỗ trợ: %', old.status;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_match_player_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_match_id uuid;
    v_status text;
begin

    if tg_op = 'DELETE' then
        v_match_id := old.match_id;
    else
        v_match_id := new.match_id;
    end if;


    if v_match_id is null then
        raise exception
            'match_id không được NULL';
    end if;


    select m.status
    into v_status
    from public.matches m
    where m.id = v_match_id;

    if not found then
        raise exception
            'Không tìm thấy match %',
            v_match_id;
    end if;


    if v_status <> 'PENDING' then
        raise exception
            'Không được thay đổi match_players khi match đang ở trạng thái %. Chỉ PENDING được chỉnh sửa',
            v_status;
    end if;


    -- Không cho UPDATE chuyển một match_player
    -- từ match này sang match khác.
    if tg_op = 'UPDATE'
       and new.match_id is distinct from old.match_id then

        raise exception
            'Không được chuyển match_player sang match khác bằng UPDATE';

    end if;


    if tg_op = 'DELETE' then
        return old;
    end if;

    return new;

end;
$function$

CREATE OR REPLACE FUNCTION public.guard_tournament_registration_players()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
    new.event_name := btrim(new.event_name);

    if new.event_name = '' then
        raise exception 'EVENT_NAME_REQUIRED';
    end if;

    if char_length(new.event_name) > 200 then
        raise exception 'EVENT_NAME_TOO_LONG';
    end if;

    -- Registration đã hủy không chiếm suất.
    if new.status = 'HUY' then
        return new;
    end if;

    -- Không cho player chính xuất hiện ở registration hoạt động khác
    -- cùng giải + cùng nội dung đã normalize.
    if exists (
        select 1
        from public.tournament_registrations tr
        where tr.tournament_id = new.tournament_id
          and lower(btrim(tr.event_name)) =
              lower(btrim(new.event_name))
          and tr.status <> 'HUY'
          and tr.id <> new.id
          and (
              tr.player_id = new.player_id
              or tr.partner_player_id = new.player_id
          )
    ) then
        raise exception
            'PLAYER_ALREADY_REGISTERED_FOR_EVENT';
    end if;

    -- Partner cũng chỉ được xuất hiện một lần
    -- trong cùng tournament + normalized event.
    if new.partner_player_id is not null
       and exists (
            select 1
            from public.tournament_registrations tr
            where tr.tournament_id = new.tournament_id
              and lower(btrim(tr.event_name)) =
                  lower(btrim(new.event_name))
              and tr.status <> 'HUY'
              and tr.id <> new.id
              and (
                  tr.player_id = new.partner_player_id
                  or tr.partner_player_id = new.partner_player_id
              )
       )
    then
        raise exception
            'PARTNER_ALREADY_REGISTERED_FOR_EVENT';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_member_signup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_full_name text;
    v_login_name text;
    v_phone text;
    v_date_of_birth date;
    v_initial_rating numeric;
    v_default_rating numeric;
    v_min_rating numeric;
    v_max_rating numeric;
    v_player_id uuid;
    v_must_change_password boolean := false;
    v_membership_status text := 'PENDING';
    v_created_by uuid;

begin
    -- raw_app_meta_data is writable only by the trusted Auth Admin API.
    -- Never trust signup user_metadata, email confirmation, or password flags.
    if new.raw_app_meta_data ->> 'membership_source' = 'ADMIN_CREATE_MEMBER' then
        begin
            v_created_by := (new.raw_app_meta_data ->> 'membership_created_by')::uuid;
        exception when invalid_text_representation then
            raise exception 'ADMIN_PROVISIONING_ACTOR_REQUIRED' using errcode = '42501';
        end;
        perform 1 from public.profiles
        where id = v_created_by and role = 'ADMIN' and is_active is true
        for share;
        if not found then
            raise exception 'ADMIN_PROVISIONING_ACTOR_REQUIRED' using errcode = '42501';
        end if;
        v_membership_status := 'APPROVED';
    end if;
    select
        rs.initial_rating,
        rs.min_rating,
        rs.max_rating
    into
        v_default_rating,
        v_min_rating,
        v_max_rating
    from public.rating_settings rs
    where rs.is_active = true;

    if not found then
        raise exception 'ACTIVE_RATING_SETTINGS_REQUIRED';
    end if;

    v_full_name :=
        nullif(
            trim(
                coalesce(
                    new.raw_user_meta_data ->> 'full_name',
                    ''
                )
            ),
            ''
        );

    if v_full_name is null then
        raise exception 'FULL_NAME_REQUIRED';
    end if;

    v_login_name :=
        nullif(
            lower(
                trim(
                    coalesce(
                        new.raw_user_meta_data ->> 'login_name',
                        ''
                    )
                )
            ),
            ''
        );

    if v_login_name is not null then
        if length(v_login_name) < 3
           or length(v_login_name) > 32
           or v_login_name !~ '^[a-z0-9._-]+$'
        then
            raise exception 'INVALID_LOGIN_NAME';
        end if;

        if exists (
            select 1
            from public.profiles p
            where lower(p.login_name) = v_login_name
        ) then
            raise exception 'LOGIN_NAME_ALREADY_EXISTS';
        end if;
    end if;

    v_must_change_password :=
        coalesce(
            lower(
                trim(
                    coalesce(
                        new.raw_user_meta_data
                            ->> 'must_change_password',
                        'false'
                    )
                )
            ) = 'true',
            false
        );

    v_phone :=
        nullif(
            trim(
                coalesce(
                    new.raw_user_meta_data ->> 'phone',
                    ''
                )
            ),
            ''
        );

    begin
        v_date_of_birth :=
            nullif(
                trim(
                    coalesce(
                        new.raw_user_meta_data ->> 'date_of_birth',
                        ''
                    )
                ),
                ''
            )::date;
    exception
        when others then
            raise exception 'INVALID_DATE_OF_BIRTH';
    end;

    if v_date_of_birth is not null
       and v_date_of_birth > current_date then
        raise exception 'INVALID_DATE_OF_BIRTH';
    end if;

    begin
        v_initial_rating :=
            coalesce(
                nullif(
                    trim(
                        coalesce(
                            new.raw_user_meta_data
                                ->> 'initial_rating',
                            ''
                        )
                    ),
                    ''
                )::numeric,
                v_default_rating
            );
    exception
        when others then
            raise exception 'INVALID_INITIAL_RATING';
    end;

    if v_initial_rating < v_min_rating
       or v_initial_rating > v_max_rating then
        raise exception 'INVALID_INITIAL_RATING';
    end if;

    insert into public.players (
        full_name,
        player_type,
        phone,
        email,
        initial_rating,
        current_rating,
        status,
        joined_at,
        date_of_birth
    )
    values (
        v_full_name,
        'CLUB',
        v_phone,
        new.email,
        v_initial_rating,
        v_initial_rating,
        'ACTIVE',
        current_date,
        v_date_of_birth
    )
    returning id
    into v_player_id;

    insert into public.profiles (
        id,
        full_name,
        login_name,
        role,
        is_active,
        player_id,
        can_collect_tournament_fee,
        must_change_password,
        membership_status,
        membership_reviewed_by,
        membership_reviewed_at
    )
    values (
        new.id,
        v_full_name,
        v_login_name,
        'MEMBER',
        v_membership_status = 'APPROVED',
        v_player_id,
        false,
        v_must_change_password,
        v_membership_status,
        v_created_by,
        case when v_created_by is not null then now() end
    );

    insert into public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason
    )
    values (
        coalesce(v_created_by, new.id),
        'AUTO_PROVISION_MEMBER',
        'profiles',
        new.id,
        null,
        jsonb_build_object(
            'membership_status', v_membership_status,
            'created_by_admin', v_created_by,
            'profile_id', new.id,
            'player_id', v_player_id,
            'full_name', v_full_name,
            'login_name', v_login_name,
            'email', new.email,
            'phone', v_phone,
            'date_of_birth', v_date_of_birth,
            'initial_rating', v_initial_rating,
            'rating_min', v_min_rating,
            'rating_max', v_max_rating,
            'role', 'MEMBER',
            'player_type', 'CLUB',
            'must_change_password',
              v_must_change_password
        ),
        'MEMBER_SIGNUP_ACTIVE_RATING_SETTINGS'
    );

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.player_reference_snapshot(p_player_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_profiles bigint;
    v_match_player bigint;
    v_match_partner bigint;
    v_match_rows bigint;
    v_rating_events bigint;
    v_rating_adjustments bigint;
    v_rating_adjustment_events bigint;
    v_fund_contributions bigint;
    v_fund_payments bigint;
    v_fund_transactions bigint;
    v_tournament_player bigint;
    v_tournament_partner bigint;
    v_tournament_rows bigint;
    v_tournament_payments bigint;
    v_awards bigint;
    v_audit_logs bigint;
    v_reference_total bigint;
BEGIN
    IF p_player_id IS NULL THEN
        RAISE EXCEPTION 'PLAYER_ID_REQUIRED' USING ERRCODE = '22023';
    END IF;

    PERFORM 1 FROM public.players WHERE id = p_player_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'PLAYER_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;

    SELECT count(*) INTO v_profiles
    FROM public.profiles x WHERE x.player_id = p_player_id;

    SELECT
        count(*) FILTER (WHERE x.player_id = p_player_id),
        count(*) FILTER (WHERE x.partner_player_id = p_player_id),
        count(*) FILTER (
            WHERE x.player_id = p_player_id
               OR x.partner_player_id = p_player_id
        )
    INTO v_match_player, v_match_partner, v_match_rows
    FROM public.match_players x;

    SELECT count(*) INTO v_rating_events
    FROM public.rating_events x WHERE x.player_id = p_player_id;
    SELECT count(*) INTO v_rating_adjustments
    FROM public.rating_adjustments x WHERE x.player_id = p_player_id;
    SELECT count(*) INTO v_rating_adjustment_events
    FROM public.rating_adjustment_events x WHERE x.player_id = p_player_id;
    SELECT count(*) INTO v_fund_contributions
    FROM public.fund_contributions x WHERE x.player_id = p_player_id;
    SELECT count(*) INTO v_fund_payments
    FROM public.fund_payments x WHERE x.player_id = p_player_id;
    SELECT count(*) INTO v_fund_transactions
    FROM public.fund_transactions x WHERE x.player_id = p_player_id;

    SELECT
        count(*) FILTER (WHERE x.player_id = p_player_id),
        count(*) FILTER (WHERE x.partner_player_id = p_player_id),
        count(*) FILTER (
            WHERE x.player_id = p_player_id
               OR x.partner_player_id = p_player_id
        )
    INTO v_tournament_player, v_tournament_partner, v_tournament_rows
    FROM public.tournament_registrations x;

    SELECT count(*) INTO v_tournament_payments
    FROM public.tournament_payments x WHERE x.player_id = p_player_id;
    SELECT count(*) INTO v_awards
    FROM public.awards x WHERE x.player_id = p_player_id;

    -- Audit metadata is reported, but is not a blocking business reference.
    SELECT count(*) INTO v_audit_logs
    FROM public.audit_logs x
    WHERE x.table_name = 'players'
      AND x.record_id = p_player_id;

    v_reference_total :=
          v_profiles
        + v_match_rows
        + v_rating_events
        + v_rating_adjustments
        + v_rating_adjustment_events
        + v_fund_contributions
        + v_fund_payments
        + v_fund_transactions
        + v_tournament_rows
        + v_tournament_payments
        + v_awards;

    RETURN jsonb_build_object(
        'inventory_version', 'PLAYER-LIFECYCLE01A',
        'profile_link_count', v_profiles,
        'match_players_player_count', v_match_player,
        'match_players_partner_count', v_match_partner,
        'match_players_count', v_match_rows,
        'rating_events_count', v_rating_events,
        'rating_adjustments_count', v_rating_adjustments,
        'rating_adjustment_events_count', v_rating_adjustment_events,
        'fund_contributions_count', v_fund_contributions,
        'fund_payments_count', v_fund_payments,
        'fund_transactions_count', v_fund_transactions,
        'tournament_registrations_player_count', v_tournament_player,
        'tournament_registrations_partner_count', v_tournament_partner,
        'tournament_registrations_count', v_tournament_rows,
        'tournament_payments_count', v_tournament_payments,
        'awards_count', v_awards,
        'audit_log_count', v_audit_logs,
        'audit_logs_blocking', false,
        'reference_total', v_reference_total
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.promote_guest_player_to_member(p_profile_id uuid, p_guest_player_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_actor_id uuid := auth.uid();
    v_profile public.profiles%rowtype;
    v_temp public.players%rowtype;
    v_guest public.players%rowtype;
    v_temp_snapshot jsonb;
    v_guest_snapshot jsonb;
    v_temp_business_total bigint;
BEGIN
    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE = '42501';
    END IF;

    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.profiles p
        WHERE p.id = v_actor_id
          AND p.is_active IS TRUE
          AND (
              upper(coalesce(p.role, '')) = 'ADMIN'
              OR (coalesce(p.can_manage_members, false) AND coalesce(p.can_manage_players, false))
          )
    ) THEN
        RAISE EXCEPTION 'MEMBER_AND_PLAYER_MANAGEMENT_PERMISSION_REQUIRED'
            USING ERRCODE = '42501';
    END IF;

    SELECT * INTO v_profile
    FROM public.profiles p
    WHERE p.id = p_profile_id
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'PROFILE_NOT_FOUND'; END IF;
    IF v_profile.role <> 'MEMBER' THEN RAISE EXCEPTION 'TARGET_PROFILE_MUST_BE_MEMBER'; END IF;
    IF NOT v_profile.is_active THEN RAISE EXCEPTION 'TARGET_PROFILE_INACTIVE'; END IF;
    IF v_profile.player_id IS NULL THEN RAISE EXCEPTION 'TARGET_PROFILE_HAS_NO_TEMP_PLAYER'; END IF;
    IF v_profile.player_id = p_guest_player_id THEN
        RAISE EXCEPTION 'PROFILE_ALREADY_LINKED_TO_TARGET_PLAYER';
    END IF;

    SELECT * INTO v_temp
    FROM public.players p WHERE p.id = v_profile.player_id
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'TEMP_PLAYER_NOT_FOUND'; END IF;
    IF v_temp.player_type <> 'CLUB' OR v_temp.status <> 'ACTIVE' THEN
        RAISE EXCEPTION 'TEMP_PLAYER_NOT_ACTIVE_CLUB';
    END IF;

    SELECT * INTO v_guest
    FROM public.players p WHERE p.id = p_guest_player_id
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'GUEST_PLAYER_NOT_FOUND'; END IF;
    IF v_guest.player_type <> 'GUEST' OR v_guest.status <> 'ACTIVE' THEN
        RAISE EXCEPTION 'TARGET_PLAYER_NOT_ACTIVE_GUEST';
    END IF;

    v_temp_snapshot := public.player_reference_snapshot(v_temp.id);
    v_guest_snapshot := public.player_reference_snapshot(v_guest.id);
    v_temp_business_total :=
          (v_temp_snapshot ->> 'reference_total')::bigint
        - 1;

    IF (v_guest_snapshot ->> 'profile_link_count')::bigint <> 0 THEN
        RAISE EXCEPTION 'GUEST_PLAYER_ALREADY_LINKED';
    END IF;
    IF v_temp_business_total <> 0 THEN
        RAISE EXCEPTION 'TEMP_PLAYER_HAS_BUSINESS_DATA'
            USING ERRCODE = '23503', DETAIL = v_temp_snapshot::text;
    END IF;

    -- Preserve Guest identity, Rating and all historical rows.
    UPDATE public.players
    SET player_type = 'CLUB', updated_at = now()
    WHERE id = v_guest.id;

    -- Unlink first because profiles.player_id is UNIQUE in production.
    UPDATE public.profiles SET player_id = NULL WHERE id = v_profile.id;
    UPDATE public.players SET status = 'INACTIVE', updated_at = now()
    WHERE id = v_temp.id;
    UPDATE public.profiles SET player_id = v_guest.id WHERE id = v_profile.id;

    INSERT INTO public.audit_logs (
        user_id, action, table_name, record_id, old_data, new_data, reason
    ) VALUES (
        v_actor_id,
        'PROMOTE_GUEST_TO_MEMBER',
        'profiles',
        v_profile.id,
        jsonb_build_object(
            'profile_id', v_profile.id,
            'old_player_id', v_temp.id,
            'old_player_name', v_temp.full_name,
            'guest_player_id', v_guest.id,
            'guest_player_name', v_guest.full_name
        ),
        jsonb_build_object(
            'profile_id', v_profile.id,
            'player_id', v_guest.id,
            'player_type', 'CLUB',
            'preserved_rating', v_guest.current_rating,
            'temporary_player_id', v_temp.id,
            'temporary_player_status', 'INACTIVE',
            'inventory_version', v_temp_snapshot ->> 'inventory_version'
        ),
        'ADMIN_CONFIRMED_EXISTING_GUEST_AS_MEMBER'
    );

    RETURN jsonb_build_object(
        'ok', true,
        'profile_id', v_profile.id,
        'player_id', v_guest.id,
        'temporary_player_id', v_temp.id,
        'rating_preserved', v_guest.current_rating
    );
END;
$function$

