CREATE OR REPLACE FUNCTION public.refund_tournament_payment(p_payment_id uuid, p_amount numeric, p_reason text, p_refunded_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid;
  v_profile public.profiles%rowtype;

  v_payment public.tournament_payments%rowtype;
  v_registration public.tournament_registrations%rowtype;
  v_tournament public.tournaments%rowtype;

  v_refund_id uuid;
  v_refund_amount numeric;
  v_refund_time timestamptz;

  v_reason text;

  v_refunded_before numeric := 0;
  v_refunded_after numeric := 0;
  v_refundable_before numeric := 0;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
  v_actor := auth.uid();

  if v_actor is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select *
  into v_profile
  from public.profiles
  where id = v_actor;

  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  if coalesce(v_profile.is_active, false) = false then
    raise exception 'PROFILE_INACTIVE';
  end if;

  if upper(coalesce(v_profile.role, '')) <> 'ADMIN'
     and coalesce(v_profile.can_collect_tournament_fee, false) = false then
    raise exception 'TREASURER_PERMISSION_REQUIRED';
  end if;

  if p_payment_id is null then
    raise exception 'PAYMENT_ID_REQUIRED';
  end if;

  if p_amount is null then
    raise exception 'REFUND_AMOUNT_REQUIRED';
  end if;

  if p_amount <= 0 then
    raise exception 'REFUND_AMOUNT_MUST_BE_POSITIVE';
  end if;

  if p_refunded_at is null then
    raise exception 'REFUNDED_AT_REQUIRED';
  end if;

  v_reason :=
    nullif(
      btrim(coalesce(p_reason, '')),
      ''
    );

  if v_reason is null then
    raise exception 'REFUND_REASON_REQUIRED';
  end if;

  if char_length(v_reason) > 1000 then
    raise exception 'REFUND_REASON_TOO_LONG';
  end if;

  perform pg_advisory_xact_lock(726184504);

  select *
  into v_payment
  from public.tournament_payments
  where id = p_payment_id
  for update;

  if not found then
    raise exception 'TOURNAMENT_PAYMENT_NOT_FOUND';
  end if;

  select *
  into v_registration
  from public.tournament_registrations
  where id = v_payment.registration_id;

  if not found then
    raise exception 'REGISTRATION_NOT_FOUND';
  end if;

  select *
  into v_tournament
  from public.tournaments
  where id = v_registration.tournament_id
  for update;

  if not found then
    raise exception 'TOURNAMENT_NOT_FOUND';
  end if;

  if v_tournament.status = 'DA_QUYET_TOAN' then
    raise exception 'TOURNAMENT_ALREADY_SETTLED';
  end if;

  select coalesce(sum(r.amount), 0)
  into v_refunded_before
  from public.tournament_payment_refunds r
  where r.payment_id = p_payment_id;

  v_refundable_before :=
    v_payment.amount - v_refunded_before;

  if v_refundable_before <= 0 then
    raise exception 'PAYMENT_ALREADY_FULLY_REFUNDED';
  end if;

  if p_amount > v_refundable_before then
    raise exception 'REFUND_EXCEEDS_REFUNDABLE_AMOUNT';
  end if;

  insert into public.tournament_payment_refunds (
    payment_id,
    amount,
    refunded_at,
    reason,
    created_by
  )
  values (
    p_payment_id,
    p_amount,
    p_refunded_at,
    v_reason,
    v_actor
  )
  returning
    id,
    amount,
    refunded_at
  into
    v_refund_id,
    v_refund_amount,
    v_refund_time;

  v_refunded_after :=
    v_refunded_before + v_refund_amount;

  insert into public.audit_logs (
    user_id,
    action,
    table_name,
    record_id,
    old_data,
    new_data,
    reason,
    created_at
  )
  values (
    v_actor,
    'REFUND_TOURNAMENT_PAYMENT',
    'tournament_payment_refunds',
    v_refund_id,
    null,
    jsonb_build_object(
      'refund_id', v_refund_id,
      'payment_id', v_payment.id,
      'registration_id', v_payment.registration_id,
      'tournament_id', v_registration.tournament_id,
      'player_id', v_payment.player_id,
      'payment_amount', v_payment.amount,
      'refund_amount', v_refund_amount,
      'refunded_at', v_refund_time,
      'refunded_before', v_refunded_before,
      'refunded_after', v_refunded_after,
      'refundable_after',
        v_payment.amount - v_refunded_after,
      'engine',
        'TOURNAMENT_PAYMENT_REFUND_V1'
    ),
    v_reason,
    now()
  );

  return jsonb_build_object(
    'ok', true,
    'refund_id', v_refund_id,
    'payment_id', v_payment.id,
    'registration_id', v_payment.registration_id,
    'tournament_id', v_registration.tournament_id,
    'payment_amount', v_payment.amount,
    'refund_amount', v_refund_amount,
    'refunded_before', v_refunded_before,
    'refunded_after', v_refunded_after,
    'refundable_after',
      v_payment.amount - v_refunded_after,
    'fully_refunded',
      (
        v_payment.amount - v_refunded_after = 0
      )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_match_by_opponent(p_match_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid;
  v_actor_player_id uuid;

  v_match public.matches%rowtype;

  v_creator_player_id uuid;
  v_creator_team text;
  v_actor_team text;

  v_reason text;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
  perform pg_advisory_xact_lock(726184501);

  v_actor := auth.uid();

  if v_actor is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if p_match_id is null then
    raise exception 'MATCH_ID_REQUIRED';
  end if;

  v_reason := nullif(btrim(p_reason), '');

  if v_reason is null then
    raise exception 'REJECTION_REASON_REQUIRED';
  end if;

  if char_length(v_reason) < 3 then
    raise exception 'REJECTION_REASON_TOO_SHORT';
  end if;

  if char_length(v_reason) > 1000 then
    raise exception 'REJECTION_REASON_TOO_LONG';
  end if;

  select pr.player_id
  into v_actor_player_id
  from public.profiles pr
  join public.players p
    on p.id = pr.player_id
  where pr.id = v_actor
    and pr.role = 'MEMBER'
    and pr.is_active = true
    and p.player_type = 'CLUB'
    and p.status = 'ACTIVE';

  if not found
     or v_actor_player_id is null then
    raise exception 'ACTIVE_MEMBER_PLAYER_REQUIRED';
  end if;

  select *
  into v_match
  from public.matches
  where id = p_match_id
  for update;

  if not found then
    raise exception 'MATCH_NOT_FOUND';
  end if;

  if v_match.status <> 'PENDING' then
    raise exception 'MATCH_NOT_PENDING';
  end if;

  if v_match.match_type not in (
    'CLUB_RATED',
    'FRIENDLY_RATED'
  ) then
    raise exception
      'OPPONENT_CONFIRMATION_NOT_ALLOWED_FOR_MATCH_TYPE';
  end if;

  if v_match.tournament_id is not null
     or v_match.league_id is not null then
    raise exception
      'OPPONENT_CONFIRMATION_REQUIRES_STANDARD_MATCH';
  end if;

  if v_match.created_by = v_actor then
    raise exception 'CREATOR_CANNOT_REJECT';
  end if;

  if v_match.opponent_rejected_by is not null then
    raise exception 'MATCH_ALREADY_REJECTED';
  end if;

  select
    (al.new_data ->> 'member_player_id')::uuid
  into v_creator_player_id
  from public.audit_logs al
  where al.record_id = p_match_id
    and al.table_name = 'matches'
    and al.action = 'CREATE_MY_PENDING_MATCH'
    and al.user_id = v_match.created_by
  order by al.created_at asc
  limit 1;

  if not found
     or v_creator_player_id is null then
    raise exception 'MEMBER_CREATED_MATCH_REQUIRED';
  end if;

  select mp.team
  into v_creator_team
  from public.match_players mp
  where mp.match_id = p_match_id
    and mp.player_id = v_creator_player_id;

  if not found then
    raise exception 'CREATOR_PLAYER_NOT_IN_MATCH';
  end if;

  select mp.team
  into v_actor_team
  from public.match_players mp
  where mp.match_id = p_match_id
    and mp.player_id = v_actor_player_id;

  if not found then
    raise exception 'REJECTOR_NOT_IN_MATCH';
  end if;

  if v_actor_team = v_creator_team then
    raise exception 'CREATOR_TEAM_CANNOT_REJECT';
  end if;

  update public.matches
  set
    opponent_rejected_by = v_actor,
    opponent_rejected_at = now(),
    opponent_rejection_reason = v_reason,

    -- defensive reset
    opponent_confirmed_by = null,
    opponent_confirmed_at = null,

    updated_at = now()
  where id = p_match_id;

  insert into public.audit_logs (
    user_id,
    action,
    table_name,
    record_id,
    old_data,
    new_data,
    reason,
    created_at
  )
  values (
    v_actor,
    'REJECT_MATCH_BY_OPPONENT',
    'matches',
    p_match_id,

    jsonb_build_object(
      'status',
      v_match.status,
      'opponent_rejected_by',
      v_match.opponent_rejected_by,
      'opponent_rejected_at',
      v_match.opponent_rejected_at,
      'opponent_rejection_reason',
      v_match.opponent_rejection_reason
    ),

    jsonb_build_object(
      'status',
      'PENDING',
      'opponent_rejected_by',
      v_actor,
      'opponent_rejected_at',
      now(),
      'engine',
      'MATCH_OPPONENT_REJECTION_P1_2B'
    ),

    v_reason,
    now()
  );

  return jsonb_build_object(
    'success',
    true,
    'match_id',
    p_match_id,
    'status',
    'PENDING',
    'opponent_rejected_by',
    v_actor,
    'rejection_reason',
    v_reason
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_pending_match(p_match_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_user_id uuid;
    v_role text;
    v_is_active boolean;
    v_can_approve_matches boolean;
    v_match public.matches%rowtype;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    perform pg_advisory_xact_lock(726184501);

    if p_match_id is null then
        raise exception 'MATCH_ID_REQUIRED';
    end if;

    if p_reason is null
       or btrim(p_reason) = '' then
        raise exception 'REJECT_REASON_REQUIRED';
    end if;

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception 'AUTH_REQUIRED';
    end if;

    select
        role,
        is_active,
        can_approve_matches
    into
        v_role,
        v_is_active,
        v_can_approve_matches
    from public.profiles
    where id = v_user_id;

    if not found then
        raise exception 'PROFILE_NOT_FOUND';
    end if;

    if coalesce(v_is_active, false) = false then
        raise exception 'ACCOUNT_INACTIVE';
    end if;

    if upper(coalesce(v_role, '')) <> 'ADMIN'
       and coalesce(v_can_approve_matches, false) = false then
        raise exception 'MATCH_APPROVAL_PERMISSION_REQUIRED';
    end if;

    select *
    into v_match
    from public.matches
    where id = p_match_id
    for update;

    if not found then
        raise exception 'MATCH_NOT_FOUND';
    end if;

    if v_match.status <> 'PENDING' then
        raise exception
            'MATCH_NOT_PENDING: %',
            v_match.status;
    end if;

    perform set_config(
        'app.match_workflow',
        'REJECT_MATCH',
        true
    );

    update public.matches
    set
        status = 'INVALID',
        invalid_reason = btrim(p_reason),
        updated_at = now()
    where id = p_match_id;

    perform set_config(
        'app.match_workflow',
        '',
        true
    );

    insert into public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason,
        created_at
    )
    values (
        v_user_id,
        'REJECT_PENDING_MATCH',
        'matches',
        p_match_id,
        jsonb_build_object(
            'status', v_match.status,
            'invalid_reason', v_match.invalid_reason
        ),
        jsonb_build_object(
            'status', 'INVALID',
            'invalid_reason', btrim(p_reason),
            'engine', 'MATCH_REJECT_V1'
        ),
        btrim(p_reason),
        now()
    );

    return jsonb_build_object(
        'success', true,
        'match_id', p_match_id,
        'status_before', v_match.status,
        'status_after', 'INVALID',
        'reason', btrim(p_reason)
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.resubmit_my_rejected_match(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid;
  v_match public.matches%rowtype;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
  perform pg_advisory_xact_lock(726184501);

  v_actor := auth.uid();

  if v_actor is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if p_match_id is null then
    raise exception 'MATCH_ID_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.profiles pr
    where pr.id = v_actor
      and pr.role = 'MEMBER'
      and pr.is_active = true
  ) then
    raise exception 'ACTIVE_MEMBER_REQUIRED';
  end if;

  select *
  into v_match
  from public.matches
  where id = p_match_id
  for update;

  if not found then
    raise exception 'MATCH_NOT_FOUND';
  end if;

  if v_match.status <> 'PENDING' then
    raise exception 'MATCH_NOT_PENDING';
  end if;

  if v_match.created_by <> v_actor then
    raise exception 'ONLY_CREATOR_CAN_RESUBMIT';
  end if;

  if v_match.opponent_rejected_by is null then
    raise exception 'MATCH_NOT_REJECTED';
  end if;

  if not exists (
    select 1
    from public.audit_logs al
    where al.record_id = p_match_id
      and al.table_name = 'matches'
      and al.action = 'CREATE_MY_PENDING_MATCH'
      and al.user_id = v_actor
  ) then
    raise exception 'MEMBER_CREATED_MATCH_REQUIRED';
  end if;

  update public.matches
  set
    opponent_rejected_by = null,
    opponent_rejected_at = null,
    opponent_rejection_reason = null,
    opponent_confirmed_by = null,
    opponent_confirmed_at = null,
    updated_at = now()
  where id = p_match_id;

  insert into public.audit_logs (
    user_id,
    action,
    table_name,
    record_id,
    old_data,
    new_data,
    reason,
    created_at
  )
  values (
    v_actor,
    'RESUBMIT_MATCH_BY_CREATOR',
    'matches',
    p_match_id,

    jsonb_build_object(
      'status',
      v_match.status,
      'opponent_rejected_by',
      v_match.opponent_rejected_by,
      'opponent_rejected_at',
      v_match.opponent_rejected_at,
      'opponent_rejection_reason',
      v_match.opponent_rejection_reason
    ),

    jsonb_build_object(
      'status',
      'PENDING',
      'opponent_rejected_by',
      null,
      'opponent_rejected_at',
      null,
      'engine',
      'MATCH_OPPONENT_RESUBMIT_P1_2B'
    ),

    'Creator chỉnh sửa và gửi lại trận để đối thủ xác nhận',
    now()
  );

  return jsonb_build_object(
    'success',
    true,
    'match_id',
    p_match_id,
    'status',
    'PENDING',
    'resubmitted',
    true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reverse_tournament_expense(p_expense_id uuid, p_reason text, p_reversed_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid;
  v_profile public.profiles%rowtype;

  v_expense public.tournament_expenses%rowtype;
  v_tournament public.tournaments%rowtype;

  v_reversal_id uuid;
  v_reason text;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
  -- AUTH
  v_actor := auth.uid();

  if v_actor is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select *
  into v_profile
  from public.profiles
  where id = v_actor;

  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  if coalesce(v_profile.is_active, false) = false then
    raise exception 'PROFILE_INACTIVE';
  end if;

  if upper(coalesce(v_profile.role, '')) <> 'ADMIN'
     and coalesce(v_profile.can_manage_tournaments, false) = false then
    raise exception
      'TOURNAMENT_MANAGEMENT_PERMISSION_REQUIRED';
  end if;

  -- INPUT
  if p_expense_id is null then
    raise exception 'EXPENSE_ID_REQUIRED';
  end if;

  if p_reversed_at is null then
    raise exception 'REVERSED_AT_REQUIRED';
  end if;

  v_reason :=
    nullif(
      btrim(coalesce(p_reason, '')),
      ''
    );

  if v_reason is null then
    raise exception 'REVERSAL_REASON_REQUIRED';
  end if;

  if char_length(v_reason) > 1000 then
    raise exception 'REVERSAL_REASON_TOO_LONG';
  end if;

  perform pg_advisory_xact_lock(726184505);

  -- EXPENSE
  select *
  into v_expense
  from public.tournament_expenses
  where id = p_expense_id
  for update;

  if not found then
    raise exception 'TOURNAMENT_EXPENSE_NOT_FOUND';
  end if;

  -- TOURNAMENT
  select *
  into v_tournament
  from public.tournaments
  where id = v_expense.tournament_id
  for update;

  if not found then
    raise exception 'TOURNAMENT_NOT_FOUND';
  end if;

  if v_tournament.status = 'DA_QUYET_TOAN' then
    raise exception 'TOURNAMENT_ALREADY_SETTLED';
  end if;

  -- DUPLICATE REVERSAL GUARD
  if exists (
    select 1
    from public.tournament_expense_reversals r
    where r.expense_id = p_expense_id
  ) then
    raise exception 'EXPENSE_ALREADY_REVERSED';
  end if;

  -- APPEND REVERSAL
  insert into public.tournament_expense_reversals (
    expense_id,
    reversed_at,
    reason,
    created_by
  )
  values (
    p_expense_id,
    p_reversed_at,
    v_reason,
    v_actor
  )
  returning id
  into v_reversal_id;

  -- AUDIT
  insert into public.audit_logs (
    user_id,
    action,
    table_name,
    record_id,
    old_data,
    new_data,
    reason,
    created_at
  )
  values (
    v_actor,
    'REVERSE_TOURNAMENT_EXPENSE',
    'tournament_expense_reversals',
    v_reversal_id,

    null,

    jsonb_build_object(
      'reversal_id', v_reversal_id,
      'expense_id', v_expense.id,
      'tournament_id', v_expense.tournament_id,
      'expense_amount', v_expense.amount,
      'expense_category', v_expense.category,
      'expense_description', v_expense.description,
      'reversed_at', p_reversed_at,
      'engine', 'TOURNAMENT_EXPENSE_REVERSAL_V1'
    ),

    v_reason,
    now()
  );

  return jsonb_build_object(
    'ok', true,
    'reversal_id', v_reversal_id,
    'expense_id', v_expense.id,
    'tournament_id', v_expense.tournament_id,
    'expense_amount', v_expense.amount,
    'reversed_at', p_reversed_at,
    'reason', v_reason
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.set_player_initial_rating_before_history(p_player_id uuid, p_rating numeric, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_actor uuid;
    v_reason text;
    v_old public.players%rowtype;
    v_new public.players%rowtype;
    v_settings public.rating_settings%rowtype;
    v_settings_count bigint;
    v_changed_at timestamptz := clock_timestamp();
BEGIN
    v_actor := auth.uid();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE = '42501';
    END IF;

    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.profiles p
        WHERE p.id = v_actor
          AND p.is_active IS TRUE
          AND upper(coalesce(p.role, '')) = 'ADMIN'
    ) THEN
        RAISE EXCEPTION 'ADMIN_REQUIRED' USING ERRCODE = '42501';
    END IF;

    IF p_player_id IS NULL THEN
        RAISE EXCEPTION 'PLAYER_ID_REQUIRED' USING ERRCODE = '22023';
    END IF;

    IF p_rating IS NULL OR p_rating::text IN ('NaN', 'Infinity', '-Infinity') THEN
        RAISE EXCEPTION 'PLAYER_RATING_REQUIRED' USING ERRCODE = '22023';
    END IF;

    v_reason := nullif(btrim(p_reason), '');
    IF v_reason IS NULL OR char_length(v_reason) > 1000 THEN
        RAISE EXCEPTION 'REASON_REQUIRED_MAX_1000' USING ERRCODE = '22023';
    END IF;

    -- This order is shared with the authoritative Rating engine.
    PERFORM pg_advisory_xact_lock(726184501);

    SELECT * INTO v_old
    FROM public.players p
    WHERE p.id = p_player_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PLAYER_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;

    SELECT count(*) INTO v_settings_count
    FROM public.rating_settings s
    WHERE s.is_active IS TRUE;

    IF v_settings_count <> 1 THEN
        RAISE EXCEPTION 'RATING_ACTIVE_SETTINGS_INVALID';
    END IF;

    SELECT * INTO v_settings
    FROM public.rating_settings s
    WHERE s.is_active IS TRUE;

    IF v_settings.min_rating < 2 OR v_settings.max_rating > 8
       OR v_settings.min_rating >= v_settings.max_rating
       OR v_settings.initial_rating < v_settings.min_rating
       OR v_settings.initial_rating > v_settings.max_rating THEN
        RAISE EXCEPTION 'RATING_ACTIVE_SETTINGS_HARD_RANGE_CONFLICT';
    END IF;

    IF p_rating < v_settings.min_rating OR p_rating > v_settings.max_rating
       OR p_rating < 2 OR p_rating > 8 THEN
        RAISE EXCEPTION 'PLAYER_RATING_OUT_OF_RANGE' USING ERRCODE = '22023';
    END IF;

    -- Recompute only after both the global Rating lock and Player row lock.
    IF public.player_has_approved_rated_history(v_old.id) THEN
        RAISE EXCEPTION 'PLAYER_RATING_HISTORY_EXISTS' USING ERRCODE = '55000';
    END IF;

    IF v_old.initial_rating IS DISTINCT FROM v_old.current_rating THEN
        RAISE EXCEPTION 'PLAYER_RATING_STATE_INCONSISTENT'
            USING ERRCODE = '55000',
                  DETAIL = format(
                      'player_id=%s old_initial_rating=%s old_current_rating=%s',
                      v_old.id, v_old.initial_rating, v_old.current_rating
                  );
    END IF;

    IF v_old.initial_rating = p_rating THEN
        RETURN jsonb_build_object(
            'success', true,
            'changed', false,
            'player_id', v_old.id,
            'old_initial_rating', v_old.initial_rating,
            'old_current_rating', v_old.current_rating,
            'new_initial_rating', v_old.initial_rating,
            'new_current_rating', v_old.current_rating,
            'rating_settings_version', v_settings.algorithm_version,
            'reason', v_reason
        );
    END IF;

    UPDATE public.players
    SET initial_rating = p_rating,
        current_rating = p_rating,
        updated_at = v_changed_at
    WHERE id = v_old.id
    RETURNING * INTO v_new;

    INSERT INTO public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason,
        created_at
    ) VALUES (
        v_actor,
        'PLAYER_INITIAL_RATING_CHANGED',
        'players',
        v_new.id,
        jsonb_build_object(
            'player_id', v_old.id,
            'initial_rating', v_old.initial_rating,
            'current_rating', v_old.current_rating,
            'rating_settings_version', v_settings.algorithm_version
        ),
        jsonb_build_object(
            'player_id', v_new.id,
            'initial_rating', v_new.initial_rating,
            'current_rating', v_new.current_rating,
            'rating_settings_version', v_settings.algorithm_version,
            'changed_at', v_changed_at
        ),
        v_reason,
        v_changed_at
    );

    RETURN jsonb_build_object(
        'success', true,
        'changed', true,
        'player_id', v_new.id,
        'old_initial_rating', v_old.initial_rating,
        'old_current_rating', v_old.current_rating,
        'new_initial_rating', v_new.initial_rating,
        'new_current_rating', v_new.current_rating,
        'rating_settings_version', v_settings.algorithm_version,
        'reason', v_reason
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_player_lifecycle_status(p_player_id uuid, p_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_actor uuid;
    v_status text;
    v_reason text;
    v_old public.players%rowtype;
    v_new public.players%rowtype;
BEGIN
    v_actor := auth.uid();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE = '42501';
    END IF;

    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.profiles p
        WHERE p.id = v_actor
          AND p.is_active IS TRUE
          AND (
              upper(coalesce(p.role, '')) = 'ADMIN'
              OR coalesce(p.can_manage_player_lifecycle, false)
          )
    ) THEN
        RAISE EXCEPTION 'PLAYER_LIFECYCLE_PERMISSION_REQUIRED'
            USING ERRCODE = '42501';
    END IF;

    IF p_player_id IS NULL THEN
        RAISE EXCEPTION 'PLAYER_ID_REQUIRED' USING ERRCODE = '22023';
    END IF;

    v_status := upper(btrim(coalesce(p_status, '')));
    IF v_status NOT IN ('ACTIVE', 'INACTIVE') THEN
        RAISE EXCEPTION 'PLAYER_STATUS_INVALID' USING ERRCODE = '22023';
    END IF;

    v_reason := nullif(btrim(p_reason), '');
    IF v_reason IS NULL OR char_length(v_reason) > 1000 THEN
        RAISE EXCEPTION 'REASON_REQUIRED_MAX_1000' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_old
    FROM public.players p
    WHERE p.id = p_player_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PLAYER_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;

    IF v_old.status = v_status THEN
        RETURN jsonb_build_object(
            'success', true,
            'changed', false,
            'player_id', v_old.id,
            'old_status', v_old.status,
            'new_status', v_old.status,
            'reason', v_reason
        );
    END IF;

    UPDATE public.players
    SET status = v_status
    WHERE id = v_old.id
    RETURNING * INTO v_new;

    INSERT INTO public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason
    ) VALUES (
        v_actor,
        'PLAYER_STATUS_CHANGED',
        'players',
        v_new.id,
        jsonb_build_object('status', v_old.status),
        jsonb_build_object('status', v_new.status),
        v_reason
    );

    RETURN jsonb_build_object(
        'success', true,
        'changed', true,
        'player_id', v_new.id,
        'old_status', v_old.status,
        'new_status', v_new.status,
        'reason', v_reason
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_profile_player_link(p_profile_id uuid, p_player_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_actor_profile public.profiles%rowtype;
    v_target_old public.profiles%rowtype;
    v_target_new public.profiles%rowtype;
    v_player public.players%rowtype;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    v_actor := auth.uid();

    if v_actor is null then
        raise exception 'AUTH_REQUIRED';
    end if;

    select *
    into v_actor_profile
    from public.profiles
    where id = v_actor;

    if not found
       or v_actor_profile.is_active <> true
       or v_actor_profile.role <> 'ADMIN' then
        raise exception 'ADMIN_REQUIRED';
    end if;

    if p_profile_id is null then
        raise exception 'PROFILE_ID_REQUIRED';
    end if;

    select *
    into v_target_old
    from public.profiles
    where id = p_profile_id
    for update;

    if not found then
        raise exception 'PROFILE_NOT_FOUND';
    end if;

    if p_player_id is not null then
        select *
        into v_player
        from public.players
        where id = p_player_id
        for share;

        if not found then
            raise exception 'PLAYER_NOT_FOUND';
        end if;

        if v_player.player_type <> 'CLUB' then
            raise exception 'PLAYER_MUST_BE_CLUB';
        end if;

        if v_player.status <> 'ACTIVE' then
            raise exception 'PLAYER_NOT_ACTIVE';
        end if;

        if exists (
            select 1
            from public.profiles p
            where p.player_id = p_player_id
              and p.id <> p_profile_id
        ) then
            raise exception 'PLAYER_ALREADY_LINKED';
        end if;
    end if;

    update public.profiles
    set
        player_id = p_player_id,
        updated_at = now()
    where id = p_profile_id
    returning *
    into v_target_new;

    insert into public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason
    )
    values (
        v_actor,
        case
            when p_player_id is null
                then 'UNLINK_PROFILE_PLAYER'
            else 'LINK_PROFILE_PLAYER'
        end,
        'profiles',
        v_target_new.id,
        to_jsonb(v_target_old),
        to_jsonb(v_target_new),
        'PROFILE_PLAYER_LINK_V1'
    );

    return jsonb_build_object(
        'success', true,
        'profile_id', v_target_new.id,
        'player_id', v_target_new.player_id,
        'linked', v_target_new.player_id is not null
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.settle_tournament(p_tournament_id uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid;
  v_profile public.profiles%rowtype;
  v_tournament public.tournaments%rowtype;

  v_summary jsonb;
  v_remaining numeric := 0;
  v_note text;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
  -- AUTH
  v_actor := auth.uid();

  if v_actor is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select *
  into v_profile
  from public.profiles
  where id = v_actor;

  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  if coalesce(v_profile.is_active, false) = false then
    raise exception 'PROFILE_INACTIVE';
  end if;

  if upper(coalesce(v_profile.role, '')) <> 'ADMIN'
     and coalesce(v_profile.can_manage_tournaments, false) = false then
    raise exception
      'TOURNAMENT_MANAGEMENT_PERMISSION_REQUIRED';
  end if;

  -- INPUT
  if p_tournament_id is null then
    raise exception 'TOURNAMENT_ID_REQUIRED';
  end if;

  v_note :=
    nullif(
      btrim(coalesce(p_note, '')),
      ''
    );

  if v_note is not null
     and char_length(v_note) > 1000 then
    raise exception 'SETTLEMENT_NOTE_TOO_LONG';
  end if;

  -- SERIALIZE TOURNAMENT FINANCE/STATUS FLOW
  perform pg_advisory_xact_lock(726184503);

  select *
  into v_tournament
  from public.tournaments
  where id = p_tournament_id
  for update;

  if not found then
    raise exception 'TOURNAMENT_NOT_FOUND';
  end if;

  if upper(v_tournament.status) = 'HUY' then
    raise exception 'TOURNAMENT_CANCELLED';
  end if;

  if upper(v_tournament.status) = 'DA_QUYET_TOAN' then
    raise exception 'TOURNAMENT_ALREADY_SETTLED';
  end if;

  if upper(v_tournament.status) <> 'DA_KET_THUC' then
    raise exception
      'TOURNAMENT_MUST_BE_COMPLETED_BEFORE_SETTLEMENT';
  end if;

  -- FINANCE SNAPSHOT
  v_summary :=
    public.get_tournament_finance_summary(
      p_tournament_id
    );

  v_remaining :=
    coalesce(
      (v_summary ->> 'remaining_total')::numeric,
      0
    );

  if v_remaining > 0 then
    raise exception
      'TOURNAMENT_HAS_OUTSTANDING_BALANCE';
  end if;

  -- STATUS TRANSITION
  update public.tournaments
  set
    status = 'DA_QUYET_TOAN',
    updated_at = now()
  where id = p_tournament_id;

  -- AUDIT
  insert into public.audit_logs (
    user_id,
    action,
    table_name,
    record_id,
    old_data,
    new_data,
    reason,
    created_at
  )
  values (
    v_actor,
    'SETTLE_TOURNAMENT',
    'tournaments',
    p_tournament_id,

    jsonb_build_object(
      'status',
      v_tournament.status
    ),

    jsonb_build_object(
      'status',
      'DA_QUYET_TOAN',

      'registration_count',
      v_summary -> 'registration_count',

      'paid_in_full_count',
      v_summary -> 'paid_in_full_count',

      'outstanding_count',
      v_summary -> 'outstanding_count',

      'fee_due_total',
      v_summary -> 'fee_due_total',

      'paid_total',
      v_summary -> 'paid_total',

      'remaining_total',
      v_summary -> 'remaining_total',

      'expense_total',
      v_summary -> 'expense_total',

      'net_cash',
      v_summary -> 'net_cash',

      'note',
      v_note,

      'engine',
      'TOURNAMENT_SETTLEMENT_V1'
    ),

    coalesce(
      v_note,
      'Quyết toán giải đấu'
    ),

    now()
  );

  return jsonb_build_object(
    'ok',
    true,

    'tournament_id',
    p_tournament_id,

    'status_before',
    v_tournament.status,

    'status_after',
    'DA_QUYET_TOAN',

    'finance',
    v_summary,

    'note',
    v_note
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_my_member_profile(p_full_name text, p_phone text DEFAULT NULL::text, p_date_of_birth date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_name text;

    v_profile_old public.profiles%rowtype;
    v_profile_new public.profiles%rowtype;

    v_player_old public.players%rowtype;
    v_player_new public.players%rowtype;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    v_actor := auth.uid();

    if v_actor is null then
        raise exception 'AUTH_REQUIRED';
    end if;

    select *
    into v_profile_old
    from public.profiles
    where id = v_actor
    for update;

    if not found then
        raise exception 'PROFILE_NOT_FOUND';
    end if;

    if v_profile_old.is_active <> true then
        raise exception 'PROFILE_INACTIVE';
    end if;

    if v_profile_old.role <> 'MEMBER' then
        raise exception 'MEMBER_REQUIRED';
    end if;

    if v_profile_old.player_id is null then
        raise exception 'PLAYER_LINK_REQUIRED';
    end if;

    select *
    into v_player_old
    from public.players
    where id = v_profile_old.player_id
    for update;

    if not found then
        raise exception 'PLAYER_NOT_FOUND';
    end if;

    if v_player_old.player_type <> 'CLUB' then
        raise exception 'PLAYER_MUST_BE_CLUB';
    end if;

    if v_player_old.status <> 'ACTIVE' then
        raise exception 'PLAYER_NOT_ACTIVE';
    end if;

    v_name :=
        nullif(
            trim(
                coalesce(
                    p_full_name,
                    ''
                )
            ),
            ''
        );

    if v_name is null then
        raise exception 'FULL_NAME_REQUIRED';
    end if;

    if char_length(v_name) > 120 then
        raise exception 'FULL_NAME_TOO_LONG';
    end if;

    if p_date_of_birth is not null
       and p_date_of_birth > current_date then
        raise exception 'INVALID_DATE_OF_BIRTH';
    end if;

    update public.players
    set
        full_name = v_name,
        phone =
            nullif(
                trim(
                    coalesce(
                        p_phone,
                        ''
                    )
                ),
                ''
            ),
        date_of_birth = p_date_of_birth,
        updated_at = now()
    where id = v_profile_old.player_id
    returning *
    into v_player_new;

    update public.profiles
    set
        full_name = v_name,
        updated_at = now()
    where id = v_actor
    returning *
    into v_profile_new;

    insert into public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason
    )
    values (
        v_actor,
        'UPDATE_MY_MEMBER_PROFILE',
        'players',
        v_player_new.id,
        jsonb_build_object(
            'profile',
            to_jsonb(v_profile_old),
            'player',
            to_jsonb(v_player_old)
        ),
        jsonb_build_object(
            'profile',
            to_jsonb(v_profile_new),
            'player',
            to_jsonb(v_player_new)
        ),
        'MEMBER_SELF_SERVICE_V1'
    );

    return jsonb_build_object(
        'success', true,
        'profile_id', v_profile_new.id,
        'player_id', v_player_new.id,
        'full_name', v_player_new.full_name,
        'phone', v_player_new.phone,
        'date_of_birth', v_player_new.date_of_birth
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_my_rejected_pending_match(p_match_id uuid, p_played_at timestamp with time zone, p_match_type text, p_score_mode text, p_team_a_score integer, p_team_b_score integer, p_team_a_player_1 uuid, p_team_a_player_2 uuid, p_team_b_player_1 uuid, p_team_b_player_2 uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor uuid;
  v_my_player_id uuid;
  v_match public.matches%rowtype;

  v_distinct_count integer;
  v_found_count integer;
  v_active_count integer;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
  perform pg_advisory_xact_lock(726184501);

  v_actor := auth.uid();

  if v_actor is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select pr.player_id
  into v_my_player_id
  from public.profiles pr
  join public.players p
    on p.id = pr.player_id
  where pr.id = v_actor
    and pr.role = 'MEMBER'
    and pr.is_active = true
    and p.player_type = 'CLUB'
    and p.status = 'ACTIVE';

  if not found
     or v_my_player_id is null then
    raise exception 'ACTIVE_MEMBER_PLAYER_REQUIRED';
  end if;

  if p_match_id is null then
    raise exception 'MATCH_ID_REQUIRED';
  end if;

  select *
  into v_match
  from public.matches
  where id = p_match_id
  for update;

  if not found then
    raise exception 'MATCH_NOT_FOUND';
  end if;

  if v_match.status <> 'PENDING' then
    raise exception 'MATCH_NOT_PENDING';
  end if;

  if v_match.created_by <> v_actor then
    raise exception 'ONLY_CREATOR_CAN_EDIT';
  end if;

  if v_match.opponent_rejected_by is null then
    raise exception 'MATCH_NOT_REJECTED';
  end if;

  if not exists (
    select 1
    from public.audit_logs al
    where al.record_id = p_match_id
      and al.table_name = 'matches'
      and al.action = 'CREATE_MY_PENDING_MATCH'
      and al.user_id = v_actor
  ) then
    raise exception 'MEMBER_CREATED_MATCH_REQUIRED';
  end if;

  if p_match_type not in (
    'CLUB_RATED',
    'FRIENDLY_RATED',
    'TRAINING'
  ) then
    raise exception 'MEMBER_MATCH_TYPE_NOT_ALLOWED';
  end if;

  if p_score_mode not in (
    'POINTS',
    'RESULT'
  ) then
    raise exception 'INVALID_SCORE_MODE';
  end if;

  if p_played_at is null then
    raise exception 'PLAYED_AT_REQUIRED';
  end if;

  if p_team_a_score is null
     or p_team_b_score is null then
    raise exception 'SCORE_REQUIRED';
  end if;

  if p_team_a_score < 0
     or p_team_b_score < 0 then
    raise exception 'NEGATIVE_SCORE_NOT_ALLOWED';
  end if;

  if p_score_mode = 'POINTS'
     and (
       p_team_a_score +
       p_team_b_score
     ) <= 0 then
    raise exception 'POINTS_SCORE_MUST_HAVE_RESULT';
  end if;

  if p_score_mode = 'RESULT' then
    if p_team_a_score not in (0,1)
       or p_team_b_score not in (0,1) then
      raise exception 'RESULT_SCORE_MUST_BE_0_OR_1';
    end if;

    if p_team_a_score = 0
       and p_team_b_score = 0 then
      raise exception 'RESULT_SCORE_MUST_HAVE_WINNER';
    end if;
  end if;

  if p_team_a_player_1 is null
     or p_team_a_player_2 is null
     or p_team_b_player_1 is null
     or p_team_b_player_2 is null then
    raise exception 'FOUR_PLAYERS_REQUIRED';
  end if;

  select count(distinct x)
  into v_distinct_count
  from unnest(
    array[
      p_team_a_player_1,
      p_team_a_player_2,
      p_team_b_player_1,
      p_team_b_player_2
    ]::uuid[]
  ) t(x);

  if v_distinct_count <> 4 then
    raise exception 'PLAYERS_MUST_BE_DISTINCT';
  end if;

  if not (
    v_my_player_id = p_team_a_player_1
    or v_my_player_id = p_team_a_player_2
    or v_my_player_id = p_team_b_player_1
    or v_my_player_id = p_team_b_player_2
  ) then
    raise exception 'MEMBER_MUST_PARTICIPATE';
  end if;

  select count(*)
  into v_found_count
  from public.players p
  where p.id = any(
    array[
      p_team_a_player_1,
      p_team_a_player_2,
      p_team_b_player_1,
      p_team_b_player_2
    ]::uuid[]
  );

  if v_found_count <> 4 then
    raise exception 'PLAYER_NOT_FOUND';
  end if;

  select count(*)
  into v_active_count
  from public.players p
  where p.id = any(
    array[
      p_team_a_player_1,
      p_team_a_player_2,
      p_team_b_player_1,
      p_team_b_player_2
    ]::uuid[]
  )
    and p.status = 'ACTIVE';

  if v_active_count <> 4 then
    raise exception 'ALL_PLAYERS_MUST_BE_ACTIVE';
  end if;

  update public.matches
  set
    played_at = p_played_at,
    match_type = p_match_type,
    score_mode = p_score_mode,
    team_a_score = p_team_a_score,
    team_b_score = p_team_b_score,
    notes = nullif(btrim(p_notes), ''),
    updated_at = now()
  where id = p_match_id;

  delete from public.match_players
  where match_id = p_match_id;

  insert into public.match_players (
    match_id,
    player_id,
    team,
    partner_player_id,
    created_at
  )
  values
    (
      p_match_id,
      p_team_a_player_1,
      'A',
      p_team_a_player_2,
      now()
    ),
    (
      p_match_id,
      p_team_a_player_2,
      'A',
      p_team_a_player_1,
      now()
    ),
    (
      p_match_id,
      p_team_b_player_1,
      'B',
      p_team_b_player_2,
      now()
    ),
    (
      p_match_id,
      p_team_b_player_2,
      'B',
      p_team_b_player_1,
      now()
    );

  insert into public.audit_logs (
    user_id,
    action,
    table_name,
    record_id,
    old_data,
    new_data,
    reason,
    created_at
  )
  values (
    v_actor,
    'UPDATE_MY_REJECTED_PENDING_MATCH',
    'matches',
    p_match_id,

    jsonb_build_object(
      'played_at', v_match.played_at,
      'match_type', v_match.match_type,
      'score_mode', v_match.score_mode,
      'team_a_score', v_match.team_a_score,
      'team_b_score', v_match.team_b_score,
      'notes', v_match.notes
    ),

    jsonb_build_object(
      'played_at', p_played_at,
      'match_type', p_match_type,
      'score_mode', p_score_mode,
      'team_a_score', p_team_a_score,
      'team_b_score', p_team_b_score,
      'team_a', jsonb_build_array(
        p_team_a_player_1,
        p_team_a_player_2
      ),
      'team_b', jsonb_build_array(
        p_team_b_player_1,
        p_team_b_player_2
      ),
      'notes',
        nullif(btrim(p_notes), ''),
      'engine',
        'MEMBER_REJECTED_MATCH_EDIT_P1_2B'
    ),

    'Creator sửa trận sau khi đối thủ từ chối xác nhận',
    now()
  );

  return jsonb_build_object(
    'success', true,
    'match_id', p_match_id,
    'status', 'PENDING',
    'rejected', true,
    'updated', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_pending_match(p_match_id uuid, p_played_at timestamp with time zone, p_match_number integer, p_match_type text, p_score_mode text, p_team_a_score integer, p_team_b_score integer, p_tournament_id uuid DEFAULT NULL::uuid, p_league_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id uuid;
    v_role text;
    v_is_active boolean;

    v_match public.matches%ROWTYPE;

    v_tournament_status text;
    v_league_status text;

    v_tournament_changed boolean;
    v_league_changed boolean;
BEGIN
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    PERFORM pg_advisory_xact_lock(726184501);

    IF p_match_id IS NULL THEN
        RAISE EXCEPTION 'match_id không được NULL';
    END IF;

    IF p_played_at IS NULL THEN
        RAISE EXCEPTION 'played_at không được NULL';
    END IF;

    IF p_match_type IS NULL
       OR btrim(p_match_type) = '' THEN
        RAISE EXCEPTION 'match_type không được để trống';
    END IF;

    IF p_score_mode IS NULL
       OR btrim(p_score_mode) = '' THEN
        RAISE EXCEPTION 'score_mode không được để trống';
    END IF;

    IF p_team_a_score IS NULL
       OR p_team_b_score IS NULL THEN
        RAISE EXCEPTION 'Tỷ số không được NULL';
    END IF;

    IF p_team_a_score < 0
       OR p_team_b_score < 0 THEN
        RAISE EXCEPTION 'Tỷ số không được âm';
    END IF;

    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION
            'Bạn chưa đăng nhập hoặc phiên đăng nhập không hợp lệ';
    END IF;

    SELECT role, is_active
    INTO v_role, v_is_active
    FROM public.profiles
    WHERE id = v_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Không tìm thấy hồ sơ người dùng';
    END IF;

    IF coalesce(v_is_active, false) = false THEN
        RAISE EXCEPTION 'Tài khoản đã bị vô hiệu hóa';
    END IF;

    IF v_role <> 'ADMIN' THEN
        RAISE EXCEPTION
            'Chỉ ADMIN mới được sửa trận PENDING';
    END IF;

    IF p_match_type NOT IN (
        'TOURNAMENT',
        'LEAGUE',
        'CLUB_RATED',
        'FRIENDLY_RATED',
        'TRAINING'
    ) THEN
        RAISE EXCEPTION
            'match_type không được phép: %',
            p_match_type;
    END IF;

    IF p_score_mode NOT IN ('POINTS', 'RESULT') THEN
        RAISE EXCEPTION
            'score_mode không hợp lệ: %',
            p_score_mode;
    END IF;

    IF p_score_mode = 'RESULT'
       AND (
            p_team_a_score NOT IN (0, 1)
            OR p_team_b_score NOT IN (0, 1)
       ) THEN
        RAISE EXCEPTION
            'Trận RESULT chỉ chấp nhận score 0 hoặc 1';
    END IF;

    SELECT *
    INTO v_match
    FROM public.matches
    WHERE id = p_match_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Không tìm thấy trận đấu: %',
            p_match_id;
    END IF;

    IF v_match.status <> 'PENDING' THEN
        RAISE EXCEPTION
            'Chỉ được sửa trận PENDING. Trạng thái hiện tại: %',
            v_match.status;
    END IF;

    IF p_match_type = 'TOURNAMENT' THEN

        IF p_tournament_id IS NULL
           OR p_league_id IS NOT NULL THEN
            RAISE EXCEPTION
                'TOURNAMENT_REQUIRES_TOURNAMENT_ID_ONLY';
        END IF;

    ELSIF p_match_type = 'LEAGUE' THEN

        IF p_league_id IS NULL
           OR p_tournament_id IS NOT NULL THEN
            RAISE EXCEPTION
                'LEAGUE_REQUIRES_LEAGUE_ID_ONLY';
        END IF;

    ELSE

        IF p_tournament_id IS NOT NULL
           OR p_league_id IS NOT NULL THEN
            RAISE EXCEPTION
                'STANDARD_MATCH_CANNOT_HAVE_COMPETITION_ID';
        END IF;

    END IF;

    v_tournament_changed :=
        p_tournament_id IS DISTINCT FROM v_match.tournament_id;

    v_league_changed :=
        p_league_id IS DISTINCT FROM v_match.league_id;

    IF v_tournament_changed
       AND p_tournament_id IS NOT NULL THEN

        SELECT t.status
        INTO v_tournament_status
        FROM public.tournaments t
        WHERE t.id = p_tournament_id
        FOR SHARE;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'Không tìm thấy giải đấu: %',
                p_tournament_id;
        END IF;

        IF v_tournament_status NOT IN (
            'DU_KIEN',
            'MO_DANG_KY',
            'DANG_DIEN_RA'
        ) THEN
            RAISE EXCEPTION
                'Không thể chuyển trận vào giải có trạng thái %',
                v_tournament_status;
        END IF;
    END IF;

    IF v_league_changed
       AND p_league_id IS NOT NULL THEN

        SELECT l.status
        INTO v_league_status
        FROM public.leagues l
        WHERE l.id = p_league_id
        FOR SHARE;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'LEAGUE_NOT_FOUND: %',
                p_league_id;
        END IF;

        IF v_league_status NOT IN (
            'DU_KIEN',
            'DANG_DIEN_RA'
        ) THEN
            RAISE EXCEPTION
                'LEAGUE_STATUS_NOT_ATTACHABLE: %',
                v_league_status;
        END IF;
    END IF;

    UPDATE public.matches
    SET
        played_at = p_played_at,
        match_number = p_match_number,
        match_type = p_match_type,
        score_mode = p_score_mode,
        team_a_score = p_team_a_score,
        team_b_score = p_team_b_score,
        tournament_id = p_tournament_id,
        league_id = p_league_id,
        notes = nullif(btrim(p_notes), ''),
        updated_at = now()
    WHERE id = p_match_id;

    INSERT INTO public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason,
        created_at
    )
    VALUES (
        v_user_id,
        'UPDATE_PENDING_MATCH',
        'matches',
        p_match_id,

        jsonb_build_object(
            'played_at', v_match.played_at,
            'match_number', v_match.match_number,
            'match_type', v_match.match_type,
            'score_mode', v_match.score_mode,
            'team_a_score', v_match.team_a_score,
            'team_b_score', v_match.team_b_score,
            'tournament_id', v_match.tournament_id,
            'league_id', v_match.league_id,
            'notes', v_match.notes
        ),

        jsonb_build_object(
            'played_at', p_played_at,
            'match_number', p_match_number,
            'match_type', p_match_type,
            'score_mode', p_score_mode,
            'team_a_score', p_team_a_score,
            'team_b_score', p_team_b_score,
            'tournament_id', p_tournament_id,
            'league_id', p_league_id,
            'tournament_changed', v_tournament_changed,
            'league_changed', v_league_changed,
            'notes', nullif(btrim(p_notes), ''),
            'engine', 'PENDING_MATCH_WRITE_P1'
        ),

        'Cập nhật thông tin trận PENDING',
        now()
    );

    RETURN jsonb_build_object(
        'success', true,
        'match_id', p_match_id,
        'status', 'PENDING',
        'played_at', p_played_at,
        'match_number', p_match_number,
        'match_type', p_match_type,
        'score_mode', p_score_mode,
        'team_a_score', p_team_a_score,
        'team_b_score', p_team_b_score,
        'tournament_id', p_tournament_id,
        'league_id', p_league_id,
        'tournament_changed', v_tournament_changed,
        'league_changed', v_league_changed,
        'notes', nullif(btrim(p_notes), '')
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_player(p_player_id uuid, p_full_name text, p_player_type text, p_phone text, p_email text, p_status text, p_joined_at date, p_date_of_birth date, p_notes text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_actor uuid;
    v_name text;
    v_type text;
    v_asserted_status text;
    v_old public.players%rowtype;
    v_new public.players%rowtype;
BEGIN
    v_actor := auth.uid();

    IF v_actor IS NULL THEN
        RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE = '42501';
    END IF;

    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.profiles p
        WHERE p.id = v_actor
          AND p.is_active IS TRUE
          AND (
              upper(coalesce(p.role, '')) = 'ADMIN'
              OR coalesce(p.can_manage_players, false)
          )
    ) THEN
        RAISE EXCEPTION 'PLAYER_MANAGEMENT_PERMISSION_REQUIRED'
            USING ERRCODE = '42501';
    END IF;

    IF p_player_id IS NULL THEN
        RAISE EXCEPTION 'PLAYER_ID_REQUIRED' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_old
    FROM public.players p
    WHERE p.id = p_player_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'PLAYER_NOT_FOUND' USING ERRCODE = 'P0002';
    END IF;

    v_asserted_status := upper(btrim(coalesce(p_status, '')));
    IF v_asserted_status NOT IN ('ACTIVE', 'INACTIVE') THEN
        RAISE EXCEPTION 'INVALID_PLAYER_STATUS' USING ERRCODE = '22023';
    END IF;

    IF v_asserted_status <> v_old.status THEN
        RAISE EXCEPTION 'PLAYER_STATUS_CHANGE_REQUIRES_LIFECYCLE_RPC'
            USING ERRCODE = '22023';
    END IF;

    v_name := nullif(btrim(p_full_name), '');
    IF v_name IS NULL THEN
        RAISE EXCEPTION 'PLAYER_NAME_REQUIRED' USING ERRCODE = '22023';
    END IF;

    v_type := upper(btrim(coalesce(p_player_type, '')));
    IF v_type NOT IN ('CLUB', 'GUEST') THEN
        RAISE EXCEPTION 'INVALID_PLAYER_TYPE' USING ERRCODE = '22023';
    END IF;

    IF p_date_of_birth IS NOT NULL AND p_date_of_birth > current_date THEN
        RAISE EXCEPTION 'INVALID_DATE_OF_BIRTH' USING ERRCODE = '22023';
    END IF;

    UPDATE public.players
    SET
        full_name = v_name,
        player_type = v_type,
        phone = nullif(btrim(p_phone), ''),
        email = nullif(btrim(p_email), ''),
        joined_at = p_joined_at,
        date_of_birth = p_date_of_birth,
        notes = nullif(btrim(p_notes), ''),
        updated_at = now()
    WHERE id = v_old.id
    RETURNING * INTO v_new;

    INSERT INTO public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason
    ) VALUES (
        v_actor,
        'UPDATE_PLAYER',
        'players',
        v_new.id,
        to_jsonb(v_old),
        to_jsonb(v_new),
        'PLAYER_WRITE_API_V2_METADATA_ONLY'
    );

    RETURN jsonb_build_object(
        'success', true,
        'player_id', v_new.id,
        'full_name', v_new.full_name,
        'player_type', v_new.player_type,
        'status', v_new.status,
        'date_of_birth', v_new.date_of_birth
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_tournament(p_tournament_id uuid, p_name text, p_code text DEFAULT NULL::text, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_location text DEFAULT NULL::text, p_event_category text DEFAULT NULL::text, p_format text DEFAULT NULL::text, p_registration_fee numeric DEFAULT 0, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_actor uuid;
    v_profile public.profiles%rowtype;

    v_old public.tournaments%rowtype;
    v_new public.tournaments%rowtype;

    v_name text;
    v_code text;
    v_location text;
    v_event_category text;
    v_format text;
    v_notes text;
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
    v_actor := auth.uid();

    if v_actor is null then
        raise exception 'AUTH_REQUIRED';
    end if;

    select *
    into v_profile
    from public.profiles
    where id = v_actor;

    if not found then
        raise exception 'PROFILE_NOT_FOUND';
    end if;

    if v_profile.is_active is not true then
        raise exception 'ACCOUNT_INACTIVE';
    end if;

    if upper(coalesce(v_profile.role, '')) <> 'ADMIN'
       and coalesce(v_profile.can_manage_tournaments, false) = false then
        raise exception 'TOURNAMENT_MANAGEMENT_PERMISSION_REQUIRED';
    end if;

    if p_tournament_id is null then
        raise exception 'TOURNAMENT_ID_REQUIRED';
    end if;

    /*
      Lock row để tránh hai ADMIN sửa cùng giải
      tại cùng thời điểm rồi ghi đè không kiểm soát.
    */
    select *
    into v_old
    from public.tournaments
    where id = p_tournament_id
    for update;

    if not found then
        raise exception 'TOURNAMENT_NOT_FOUND';
    end if;

    v_name :=
        nullif(
            btrim(p_name),
            ''
        );

    if v_name is null then
        raise exception 'TOURNAMENT_NAME_REQUIRED';
    end if;

    if p_start_date is null then
        raise exception 'START_DATE_REQUIRED';
    end if;

    if (
        p_end_date is not null
        and p_end_date < p_start_date
    ) then
        raise exception 'END_DATE_BEFORE_START_DATE';
    end if;

    if p_registration_fee is null then
        raise exception 'REGISTRATION_FEE_REQUIRED';
    end if;

    if p_registration_fee < 0 then
        raise exception 'REGISTRATION_FEE_MUST_BE_NONNEGATIVE';
    end if;

    v_code :=
        nullif(
            btrim(p_code),
            ''
        );

    v_location :=
        nullif(
            btrim(p_location),
            ''
        );

    v_event_category :=
        nullif(
            btrim(p_event_category),
            ''
        );

    v_format :=
        nullif(
            btrim(p_format),
            ''
        );

    v_notes :=
        nullif(
            btrim(p_notes),
            ''
        );

    update public.tournaments
    set
        name = v_name,
        code = v_code,
        start_date = p_start_date,
        end_date = p_end_date,
        location = v_location,
        event_category = v_event_category,
        format = v_format,
        registration_fee = p_registration_fee,
        notes = v_notes,
        updated_at = now()
    where id = p_tournament_id
    returning *
    into v_new;

    /*
      status và created_by cố ý không nằm trong UPDATE.
      Lifecycle sẽ do RPC riêng ở V1C quản lý.
    */

    insert into public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason
    )
    values (
        v_actor,
        'UPDATE_TOURNAMENT',
        'tournaments',
        v_new.id,
        to_jsonb(v_old),
        to_jsonb(v_new),
        'Cập nhật thông tin giải đấu'
    );

    return jsonb_build_object(
        'success', true,
        'tournament_id', v_new.id,
        'name', v_new.name,
        'code', v_new.code,
        'start_date', v_new.start_date,
        'end_date', v_new.end_date,
        'location', v_new.location,
        'event_category', v_new.event_category,
        'format', v_new.format,
        'registration_fee', v_new.registration_fee,
        'status', v_new.status,
        'notes', v_new.notes,
        'updated_at', v_new.updated_at
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.void_match(p_match_id uuid, p_reason text, p_algorithm_version text DEFAULT 'V1.1'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_user_id uuid;
    v_role text;
    v_is_active boolean;
    v_can_approve_matches boolean;

    v_match public.matches%rowtype;
    v_rating_result jsonb;

    v_contribution_count integer := 0;
    v_contributions_adjusted integer := 0;

    v_original_cash_count integer := 0;
    v_refund_created_count integer := 0;
    v_existing_refund_count integer := 0;

    r_tx record;
    v_refund_transaction_id uuid;
begin
    perform pg_advisory_xact_lock(726184501);

    if p_match_id is null then
        raise exception 'match_id không được NULL';
    end if;

    if p_reason is null
       or btrim(p_reason) = '' then
        raise exception 'Lý do VOID không được để trống';
    end if;

    if p_algorithm_version is null
       or btrim(p_algorithm_version) = '' then
        raise exception 'algorithm_version không được để trống';
    end if;

    v_user_id := auth.uid();

    if v_user_id is null then
        raise exception
            'Bạn chưa đăng nhập hoặc phiên đăng nhập không hợp lệ';
    end if;

    select
        role,
        is_active,
        can_approve_matches
    into
        v_role,
        v_is_active,
        v_can_approve_matches
    from public.profiles
    where id = v_user_id;

    if not found then
        raise exception 'Không tìm thấy hồ sơ người dùng';
    end if;

    if coalesce(v_is_active, false) = false then
        raise exception 'Tài khoản đã bị vô hiệu hóa';
    end if;

    if upper(coalesce(v_role, '')) <> 'ADMIN'
       and coalesce(v_can_approve_matches, false) = false then
        raise exception 'MATCH_APPROVAL_PERMISSION_REQUIRED';
    end if;

    if not exists (
        select 1
        from public.rating_settings rs
        where rs.algorithm_version = p_algorithm_version
    ) then
        raise exception
            'Không tồn tại Rating algorithm version: %',
            p_algorithm_version;
    end if;

    select *
    into v_match
    from public.matches
    where id = p_match_id
    for update;

    if not found then
        raise exception
            'Không tìm thấy trận đấu: %',
            p_match_id;
    end if;

    if v_match.status <> 'APPROVED' then
        raise exception
            'Không thể VOID trận %. Trạng thái hiện tại: %. Chỉ APPROVED mới được VOID',
            p_match_id,
            v_match.status;
    end if;

    select count(*)
    into v_contribution_count
    from public.fund_contributions fc
    where fc.match_id = p_match_id;

    update public.fund_contributions
    set status = 'DIEU_CHINH'
    where match_id = p_match_id
      and status <> 'DIEU_CHINH';

    get diagnostics
        v_contributions_adjusted = row_count;

    for r_tx in
        select
            ft.id,
            ft.transaction_date,
            ft.transaction_type,
            ft.amount,
            ft.description,
            ft.player_id,
            ft.match_id,
            ft.payment_id
        from public.fund_transactions ft
        where ft.match_id = p_match_id
          and ft.transaction_type in (
              'THU_QUY_THUA_TRAN',
              'THU_QUY_HOA'
          )
        order by
            ft.transaction_date,
            ft.id
    loop
        v_original_cash_count :=
            v_original_cash_count + 1;

        if exists (
            select 1
            from public.fund_transactions rev
            where rev.reversal_of_transaction_id = r_tx.id
        ) then
            v_existing_refund_count :=
                v_existing_refund_count + 1;
        else
            insert into public.fund_transactions (
                transaction_date,
                transaction_type,
                amount,
                description,
                player_id,
                match_id,
                tournament_id,
                created_by,
                created_at,
                payment_id,
                reversal_of_transaction_id
            )
            values (
                now(),
                'HOAN_TIEN',
                r_tx.amount,
                'Hoàn tiền do VOID trận đấu',
                r_tx.player_id,
                r_tx.match_id,
                null,
                v_user_id,
                now(),
                null,
                r_tx.id
            )
            returning id
            into v_refund_transaction_id;

            v_refund_created_count :=
                v_refund_created_count + 1;
        end if;
    end loop;

    perform set_config(
        'app.match_workflow',
        'VOID_MATCH',
        true
    );

    update public.matches
    set
        status = 'VOIDED',
        invalid_reason = btrim(p_reason),
        updated_at = now()
    where id = p_match_id;

    perform set_config(
        'app.match_workflow',
        '',
        true
    );

    v_rating_result :=
        public._rebuild_ratings_internal(
            p_algorithm_version,
            v_user_id
        );

    insert into public.audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_data,
        new_data,
        reason,
        created_at
    )
    values (
        v_user_id,
        'VOID_MATCH',
        'matches',
        p_match_id,
        jsonb_build_object(
            'status', v_match.status,
            'invalid_reason', v_match.invalid_reason
        ),
        jsonb_build_object(
            'status', 'VOIDED',
            'void_reason', btrim(p_reason),
            'algorithm_version', p_algorithm_version,
            'contribution_count', v_contribution_count,
            'contributions_adjusted', v_contributions_adjusted,
            'original_cash_transactions', v_original_cash_count,
            'refunds_created', v_refund_created_count,
            'existing_refunds', v_existing_refund_count,
            'rating_result', v_rating_result,
            'engine', 'MATCH_VOID_V1'
        ),
        btrim(p_reason),
        now()
    );

    return jsonb_build_object(
        'success', true,
        'match_id', p_match_id,
        'status_before', v_match.status,
        'status_after', 'VOIDED',
        'reason', btrim(p_reason),
        'algorithm_version', p_algorithm_version,
        'contributions_found', v_contribution_count,
        'contributions_adjusted', v_contributions_adjusted,
        'original_cash_transactions', v_original_cash_count,
        'refunds_created', v_refund_created_count,
        'existing_refunds', v_existing_refund_count,
        'rating', v_rating_result
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.void_match_active(p_match_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
    -- ACC07B business access gate
    IF NOT public.current_user_business_access_active() THEN
        RAISE EXCEPTION 'BUSINESS_ACCESS_REQUIRED' USING ERRCODE = '42501';
    END IF;
  return public.void_match(
    p_match_id,
    p_reason,
    public._get_active_rating_version()
  );
end;
$function$
